// Lektionen 79–90 (Offenbarungsreihenfolge, Kairoer Chronologie) – Ende der Mekka-Zeit und Beginn der Medina-Zeit
window.LEKTIONEN11 = [
// ───────────────────────── Lektion 79: Al-Maʿāridsch ─────────────────────────
{
sure: 70, offb: 79, name: "Al-Maʿāridsch", arab: "سُورَةُ الْمَعَارِجِ", de: "Die Aufstiegswege", verse: 44, ort: "Mekka",
zeit: "Spätmekkanisch – Antwort auf die höhnische Forderung, die angedrohte Strafe doch endlich herbeizuholen",
kurz: "Ein Spötter in Mekka forderte: „Wenn das die Wahrheit ist, dann lass die Strafe doch gleich kommen!“ Die Sure antwortet gelassen: Die Strafe kommt sicher – von Allah, dem Herrn der Aufstiegswege, zu Dem Engel und Geist an einem Tag aufsteigen, dessen Maß fünfzigtausend Jahre ist. Deshalb: „Sei geduldig mit schöner Geduld.“ Dann zeichnet sie das ehrlichste Porträt des Menschen: „Der Mensch ist kleinmütig erschaffen – trifft ihn Übel, jammert er; trifft ihn Gutes, hält er es zurück“ – außer den Betenden. Und dann folgen acht Eigenschaften dieser Betenden: beständig im Gebet, ein festes Recht im Vermögen für Bittende und Entbehrende, Glaube an den Gerichtstag, Ehrfurcht vor der Strafe, Hüten der Scham, Treue zu anvertrauten Gütern und Verträgen, Standhaftigkeit im Zeugnis und das Hüten des Gebets. Das Gebet ist der Anfang und das Ende dieser Liste – es ist das Gegenmittel gegen die menschliche Grundschwäche.",
schluessel: {arab: "إِنَّ الْإِنسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ", ueb: "Der Mensch ist kleinmütig erschaffen: Trifft ihn Übel, ist er voller Jammer; trifft ihn Gutes, hält er es zurück – außer den Betenden.", ref: "70:19–22"},
kontext: ["Gegen Ende der Mekka-Zeit war der Spott der Quraisch zu einer Art Ritual geworden. Wenn der Prophet ﷺ vor der Strafe Allahs warnte, verlangten die Wortführer sie spöttisch sofort herbei – so wie Abū Dschahl vor Badr betete: „O Allah, wenn dies die Wahrheit von Dir ist, so lass Steine vom Himmel auf uns regnen!“ (8:32; Sahih al-Buchari, Nr. 4648). Die Sure nimmt diese Herausforderung auf, ohne sich provozieren zu lassen. Allahs Zeit ist nicht die Zeit der Ungeduldigen.",
"Der Name Al-Maʿāridsch (die Aufstiegswege, Stufen) verweist auf die Wege, über die Engel und der Rūḥ (Dschibrīl) zu Allah aufsteigen. Das Bild der fünfzigtausend Jahre deuten die Mufassirūn verschieden: als Länge des Jüngsten Tages für die Ungläubigen (so Ibn ʿAbbās in einer Überlieferung) oder als Maß der Entfernung des Aufstiegs. Der Hadith über den Zakat-Verweigerer, der „an einem Tag, dessen Maß fünfzigtausend Jahre ist“ gepeinigt wird, stützt die erste Deutung (Sahih Muslim, Nr. 987). Für den Gläubigen dagegen wird dieser Tag nach anderen Überlieferungen kurz sein.",
"Die Mitte der Sure (70:19–35) ist eine der klarsten Charakterlehren des Korans und passt genau zu deinem Tazkiya-Thema: Die Grundschwäche des Menschen (halūʿ) wird nicht geleugnet, sondern benannt. Geheilt wird sie durch ein Paket von Gewohnheiten, das mit dem Gebet beginnt und mit dem Gebet endet. Vergleiche das mit Al-Muʾminūn 23:1–11 (eine spätere Lektion), wo fast dieselbe Liste steht: Der Koran wiederholt, was er dir einprägen will."],
asbab: [
 {text: "Vers 1–3: Ibn ʿAbbās berichtet, der Fragende sei an-Naḍr ibn al-Ḥārith gewesen, der die Strafe spöttisch herbeiwünschte.", quelle: "an-Nasāʾī, as-Sunan al-kubrā (Kitāb at-Tafsīr); al-Ḥākim, al-Mustadrak – nach seiner Einstufung sahih"},
 {text: "Vergleichbar ist das Gebet Abū Dschahls: „Wenn dies die Wahrheit ist, so lass Steine auf uns regnen“ – Anlass von 8:32–33.", quelle: "Sahih al-Buchari, Nr. 4648; Sahih Muslim, Nr. 2796"}
],
begriffe: [
 {arab: "الْمَعَارِج", tr: "al-maʿāridsch", wurzel: "ʿ-r-dsch", erkl: "Aufstiegswege und Stufen – dieselbe Wurzel wie Miʿrādsch, die Himmelsreise des Propheten ﷺ. Allah ist der „Herr der Aufstiegswege“: Alles steigt zu Ihm auf, die Engel, die Seelen und die guten Worte (35:10)."},
 {arab: "صَبْرًا جَمِيلًا", tr: "ṣabran dschamīlā", wurzel: "ṣ-b-r / dsch-m-l", erkl: "„Schöne Geduld“ (70:5) – Geduld ohne Klage bei Menschen und ohne Bitterkeit. Yaʿqūb sprach dasselbe Wort beim Verlust Yūsufs (12:18). Schön ist die Geduld, die nur bei Allah klagt."},
 {arab: "هَلُوع", tr: "halūʿ", wurzel: "h-l-ʿ", erkl: "„Kleinmütig, haltlos“ – die Mischung aus Panik im Unglück und Geiz im Glück. Der Koran erklärt das Wort selbst in den nächsten beiden Versen: dschazūʿ (jammernd) und manūʿ (zurückhaltend). Das ist die Rohfassung des Menschen vor der Tazkiya."},
 {arab: "دَائِمُون", tr: "dāʾimūn", wurzel: "d-w-m", erkl: "„Beständig“ (70:23) – die erste Eigenschaft der Betenden ist nicht Länge, sondern Beständigkeit: Sie lassen ihr Gebet nicht ausfallen. Der Prophet ﷺ liebte die Tat, die beständig ist, auch wenn sie klein ist."},
 {arab: "حَقٌّ مَّعْلُوم", tr: "ḥaqqun maʿlūm", wurzel: "ḥ-q-q / ʿ-l-m", erkl: "„Ein festgesetztes Recht“ (70:24) im Vermögen für den Bittenden (sāʾil) und den Entbehrenden (maḥrūm, der aus Scham nicht fragt). Kein Almosen nach Laune, sondern ein Anspruch, den der Arme an deinem Geld hat – die mekkanische Vorstufe der Zakat."},
 {arab: "نُصُب", tr: "nuṣub", wurzel: "n-ṣ-b", erkl: "„Aufgerichtete Steine/Götzenmale“ (70:43): Am Gerichtstag eilen die Leugner aus den Gräbern, „als würden sie zu einem Götzenmal hasten“ – so wie sie im Leben zu ihren Götzen rannten. Was du im Leben ansteuerst, bestimmt die Art, wie du aufstehst."}
],
tafsir: [
 {vers: "Verse 1–18", text: "„Ein Fragender fragte nach einer Strafe, die eintreffen wird – für die Ungläubigen, die niemand abwehren kann.“ Ibn Kathīr: Die Antwort ist keine Debatte, sondern eine Feststellung; die Strafe kommt von Allah, dem Herrn der Aufstiegswege. „So sei geduldig mit schöner Geduld. Sie sehen ihn (den Tag) als fern an, Wir aber sehen ihn als nah.“ Dann das Bild des Tages: Der Himmel wie geschmolzenes Metall, die Berge wie Wollflocken (vgl. Lektion 30), kein Freund fragt nach dem Freund. Der Sünder wünscht, er könnte sich loskaufen „mit seinen Söhnen, seiner Gefährtin, seinem Bruder, seiner Sippe, die ihn beherbergte, und allen auf der Erde“. Die Reihenfolge ist erschütternd: Er bietet zuerst die an, die er am meisten liebte. „Keineswegs! Es ist ein Flammenfeuer … das ruft, wer den Rücken kehrte, sich abwandte und Vermögen sammelte und hortete.“"},
 {vers: "Verse 19–35", text: "Die Charakterlehre. As-Saʿdī: Der Mensch ist von Natur aus ungeduldig und geizig; der Koran tadelt nicht die Natur, sondern lädt ein, sie durch Gottesdienst zu formen. Die Ausnahme sind die Betenden, beschrieben in acht Zügen: (1) beständig im Gebet, (2) ein festes Recht für Bittende und Entbehrende, (3) sie halten den Gerichtstag für wahr, (4) sie fürchten die Strafe ihres Herrn – „vor der Strafe ihres Herrn ist niemand sicher“, nicht einmal der Fromme, (5) sie hüten ihre Scham außer gegenüber ihren Ehepartnern, (6) sie wahren anvertraute Güter und Verträge, (7) sie stehen zu ihren Zeugnissen, (8) sie hüten ihr Gebet. Al-Qurṭubī: Die Beständigkeit (V. 23) betrifft die Regelmäßigkeit, das Hüten (V. 34) betrifft die Bedingungen, die Zeiten und die innere Sammlung. „Diese werden in Gärten geehrt sein.“ Beachte: Halūʿ wird nicht durch Willenskraft allein geheilt, sondern durch ein ganzes Lebenssystem."},
 {vers: "Verse 36–44", text: "Die Spötter strömen von rechts und links in Grüppchen zum Propheten ﷺ, um sich lustig zu machen – „begehrt etwa jeder von ihnen, in den Garten der Wonne eingelassen zu werden?“ Ibn Kathīr: Sie hielten sich wegen ihres Ranges für selbstverständliche Anwärter auf jedes Gute. „Keineswegs! Wir haben sie aus dem erschaffen, was sie wissen“ – aus einem verächtlichen Tropfen (vgl. Lektion 31 und 33). Dann der Schwur beim „Herrn der Osten und Westen“, dass Allah sie durch Bessere ersetzen kann. Schlussbild: Sie kommen aus den Gräbern heraus, eilig wie zu einem Götzenmal, „die Blicke gesenkt, bedeckt von Erniedrigung – das ist der Tag, der ihnen versprochen war“."}
],
ahadith: [
 {text: "„Die Taten, die Allah am liebsten sind, sind die beständigsten, auch wenn sie wenig sind.“ – der Kommentar der Sunna zu dāʾimūn (70:23).", quelle: "Sahih al-Buchari, Nr. 6464; Sahih Muslim, Nr. 783"},
 {text: "Über den, der die Zakat seines Vermögens nicht entrichtet: Er wird gepeinigt „an einem Tag, dessen Maß fünfzigtausend Jahre beträgt, bis zwischen den Dienern gerichtet ist“.", quelle: "Sahih Muslim, Nr. 987"},
 {text: "„Das Schlimmste, was in einem Mann sein kann, ist ängstlicher Geiz und haltlose Feigheit.“ – das Wort hāliʿ aus diesem Hadith ist die Wurzel von halūʿ.", quelle: "Sunan Abū Dāwūd, Nr. 2511; sahih"}
],
hanafi: "Das „festgesetzte Recht“ (70:24) wurde in Medina als Zakat genau bemessen. Nach hanafitischer Schule gilt: Zakat ist farḍ, wenn das Vermögen den Nisāb (z. B. 200 Dirham Silber oder 20 Mithqāl Gold, heute nach dem Gegenwert berechnet) übersteigt und ein Mondjahr im Besitz war; der Satz beträgt 2,5 %. Eine hanafitische Besonderheit: Auch auf getragenen Gold- und Silberschmuck der Frau ist Zakat fällig, wenn er den Nisāb erreicht – die Mehrheit der anderen Schulen befreit Gebrauchsschmuck. Wenn du hanafitisch praktizierst, rechne den Schmuck also mit ein.",
umsetzung: [
 "Mach die Acht-Punkte-Liste der Betenden (70:22–35) zu deinem Monatsspiegel: Wo bin ich beständig, wo nur gelegentlich? Beginne bei Punkt 1 – keine Gebetsausfälle diesen Monat.",
 "Gegen halūʿ im Alltag: Wenn dich Unglück trifft, sprich zuerst innā lillāhi wa-innā ilaihi rādschiʿūn statt zu jammern; wenn dich Gutes trifft, gib sofort etwas davon weiter. So trainierst du beide Hälften der Schwäche.",
 "Rechne dein „festgesetztes Recht“ aus: Lege fest, welcher Anteil deines Einkommens monatlich automatisch an Bedürftige geht – und vergiss den maḥrūm nicht, der aus Scham nicht fragt.",
 "Wenn Spott oder Druck wegen deines Glaubens kommt: ṣabran dschamīlā – keine Gegenattacke, keine Bitterkeit, nur Standhaftigkeit."
]
},

// ───────────────────────── Lektion 80: An-Nabaʾ ─────────────────────────
{
sure: 78, offb: 80, name: "An-Nabaʾ", arab: "سُورَةُ النَّبَإِ", de: "Die Kunde", verse: 40, ort: "Mekka",
zeit: "Spätmekkanisch – die Eröffnungssure des letzten Dschuzʾ (ʿAmma), über die große Streitfrage Mekkas: die Auferstehung",
kurz: "„Wonach fragen sie einander? Nach der gewaltigen Kunde, über die sie uneins sind.“ Die gewaltige Kunde ist die Auferstehung. Statt lange zu streiten, stellt Allah neun Fragen aus dem Alltag: Haben Wir nicht die Erde zu einer Lagerstätte gemacht und die Berge zu Pflöcken? Euch in Paaren erschaffen, euren Schlaf zur Ruhe gemacht, die Nacht zum Kleid, den Tag zum Erwerb, sieben feste Himmel über euch gebaut, eine strahlende Lampe gesetzt und aus den Regenwolken Wasser herabgegossen? Wer all das geordnet hat, ordnet auch den Tag der Entscheidung. Dann folgen Hölle als Hinterhalt, Paradies als Erfolg, die Engel in Reihen – und der letzte Satz des Ungläubigen, der jeden Leser trifft: „O wäre ich doch Staub!“",
schluessel: {arab: "يَوْمَ يَنظُرُ الْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنتُ تُرَابًا", ueb: "Am Tag, an dem der Mensch sehen wird, was seine Hände vorausgeschickt haben, und der Ungläubige sagen wird: O wäre ich doch Staub!", ref: "78:40"},
kontext: ["Mit dieser Sure beginnt der dreißigste Teil des Korans, Dschuzʾ ʿAmma, den viele Muslime als ersten auswendig lernen. In der Offenbarungsfolge gehört sie aber nicht zum Anfang, sondern in die späte mekkanische Zeit. Nach Jahren der Verkündigung war die Auferstehung zum Dauerthema in den Versammlungen der Quraisch geworden: Man diskutierte, spottete, zweifelte. Al-Ḥasan al-Baṣrī und andere berichten, die Leute hätten einander nach dieser „Kunde“ gefragt, als der Prophet ﷺ begann, offen davon zu sprechen.",
"Die Methode der Sure ist ein Lehrstück für jede Daʿwa: keine Polemik, sondern Fragen, die jeder Zuhörer aus eigener Erfahrung beantworten kann. Ein Wüstenbewohner sieht die Berge, den Schlaf, die Nacht, die Wolken, den Regen. Wer das alles als geordnet erkennt, kann den Gedanken nicht ablehnen, dass auch das Leben auf ein geordnetes Ende zuläuft – sonst wäre die ganze Ordnung sinnlos (vgl. 75:36, Lektion 31).",
"Abū Bakr sagte zum Propheten ﷺ: „Du bist grau geworden.“ Er antwortete: „Hūd, Al-Wāqiʿa, Al-Mursalāt, ʿAmma yatasāʾalūn und Idhā sch-schamsu kuwwirat haben mich grau werden lassen“ (Sunan at-Tirmidhī, Nr. 3297). Diese Sure gehört also zu denen, deren Inhalt den Propheten ﷺ selbst körperlich gezeichnet hat."],
asbab: ["Für die Sure ist kein sahih gesicherter Einzelanlass überliefert. Die Tafsir-Werke (u. a. aṭ-Ṭabarī) berichten von al-Ḥasan al-Baṣrī und Qatāda, dass die Quraisch untereinander über die Auferstehung stritten, als der Prophet ﷺ sie verkündete – daher die Eröffnungsfrage."],
begriffe: [
 {arab: "النَّبَأ الْعَظِيم", tr: "an-nabaʾ al-ʿaẓīm", wurzel: "n-b-ʾ", erkl: "„Die gewaltige Kunde“ – nabaʾ ist eine wichtige, folgenreiche Nachricht (davon kommt nabiyy, der Prophet, der Überbringer der Kunde). Gemeint ist nach der Mehrheit der Mufassirūn die Auferstehung, nach anderen der Koran selbst."},
 {arab: "أَوْتَادًا", tr: "autādā", wurzel: "w-t-d", erkl: "„Pflöcke“ (78:7) – die Berge halten die Erde wie Zeltpflöcke das Zelt. Ein Bild aus dem Alltag der Beduinen, die ihr Leben unter Zelten verbrachten. Vgl. Pharao, „Herr der Pfähle“, in Lektion 10."},
 {arab: "سُبَاتًا", tr: "subātā", wurzel: "s-b-t", erkl: "„Ruhe/Unterbrechung“ (78:9) – der Schlaf schneidet den Menschen von seiner Arbeit ab und erneuert ihn. Jeder Schlaf ist ein kleiner Tod und jedes Erwachen eine kleine Auferstehung – das Argument der Sure steckt in deinem Bett."},
 {arab: "مِرْصَادًا", tr: "mirṣādā", wurzel: "r-ṣ-d", erkl: "„Hinterhalt/Beobachtungsposten“ (78:21) – die Hölle liegt auf der Lauer. Dieselbe Wurzel wie in 89:14 („dein Herr ist wahrlich im Hinterhalt“, Lektion 10)."},
 {arab: "أَحْقَابًا", tr: "aḥqābā", wurzel: "ḥ-q-b", erkl: "„Zeitalter um Zeitalter“ (78:23) – endlose Abfolgen langer Zeiträume. Die Mufassirūn betonen, dass das Wort Ewigkeit für die Leugner nicht begrenzt, sondern die unvorstellbare Dauer veranschaulicht."},
 {arab: "تُرَابًا", tr: "turābā", wurzel: "t-r-b", erkl: "„Staub“ (78:40) – der Wunsch des Ungläubigen. Nach den Überlieferungen sieht er, wie die Tiere nach ihrem Ausgleich zu Staub werden, und wünscht sich dasselbe Ende statt der Abrechnung."}
],
tafsir: [
 {vers: "Verse 1–16", text: "„Wonach fragen sie einander? Nach der gewaltigen Kunde, über die sie uneins sind. Keineswegs! Sie werden es erfahren. Abermals keineswegs! Sie werden es erfahren.“ Die doppelte Warnung kennst du aus 102:3–4 (Lektion 16). Dann die neun Zeichen: Erde als Lager (mihād), Berge als Pflöcke, Paare, Schlaf als Ruhe, Nacht als Kleid, Tag als Lebensunterhalt, sieben feste Himmel, eine strahlende Lampe (die Sonne) und Regen aus den Wolken, „damit Wir dadurch Korn und Pflanzen hervorbringen und dicht bewachsene Gärten“. Ibn Kathīr: Die Liste geht vom Boden unter deinen Füßen bis zum Himmel über dir und zurück zum Brot auf deinem Teller. As-Saʿdī: Wer so viel für dich vorbereitet hat, hat dich nicht zum Spielen erschaffen."},
 {vers: "Verse 17–30", text: "„Der Tag der Entscheidung (yaum al-faṣl, vgl. Lektion 33) ist ein festgesetzter Termin.“ Posaunenstoß, die Menschen kommen „in Scharen“, der Himmel öffnet sich zu Toren, die Berge werden zur Luftspiegelung. Dann die Hölle als Hinterhalt, ein Aufenthalt für die Übertreter „für Zeitalter“: kein Kühles, kein Trank außer siedendem Wasser und Eiter – „als angemessene Vergeltung“ (dschazāʾan wifāqā). Al-Qurṭubī: Die Strafe entspricht genau der Tat. Der Grund wird genannt: „Sie erwarteten keine Abrechnung und erklärten Unsere Zeichen entschieden für Lüge. Und alles haben Wir in einem Buch aufgezeichnet.“ Wer nicht mit Abrechnung rechnet, lebt ohne Bremse."},
 {vers: "Verse 31–40", text: "„Für die Gottesfürchtigen ist ein Ort des Erfolgs“: Gärten, Trauben, Gefährtinnen gleichen Alters, ein voller Becher, kein leeres Gerede und keine Lüge – „als Vergeltung von deinem Herrn, eine ausreichende Gabe (ʿaṭāʾan ḥisābā)“. Ibn Kathīr: Der Lohn wird als Gabe bezeichnet – niemand verdient das Paradies wirklich, es ist Allahs Großzügigkeit. Dann die Szene der Ehrfurcht: Der Rūḥ und die Engel stehen in Reihen, niemand spricht, außer wem der Allerbarmer erlaubt. „Das ist der wahre Tag. Wer nun will, nimmt bei seinem Herrn eine Heimstatt.“ Schluss: Der Mensch sieht, was seine Hände vorausgeschickt haben – und der Ungläubige wünscht sich, Staub zu sein. Der Hadith über den Ausgleich zwischen den Tieren (Sahih Muslim, Nr. 2582) erklärt den Hintergrund: Wenn sogar das hornlose Schaf vom gehörnten sein Recht bekommt, wie genau wird dann zwischen Menschen abgerechnet?"}
],
ahadith: [
 {text: "Abū Bakr: „O Gesandter Allahs, du bist grau geworden.“ – „Grau werden lassen haben mich Hūd, Al-Wāqiʿa, Al-Mursalāt, ʿAmma yatasāʾalūn und Idhā sch-schamsu kuwwirat.“", quelle: "Sunan at-Tirmidhī, Nr. 3297; von at-Tirmidhī als hasan eingestuft"},
 {text: "„Die Rechte werden am Tag der Auferstehung ihren Inhabern zurückerstattet, sodass sogar für das hornlose Schaf vom gehörnten Schaf Vergeltung genommen wird.“", quelle: "Sahih Muslim, Nr. 2582"},
 {text: "Beim Schlafengehen sprach der Prophet ﷺ: „In Deinem Namen, o Allah, sterbe ich und lebe ich“, und beim Aufwachen: „Gepriesen sei Allah, Der uns wieder lebendig gemacht hat, nachdem Er uns sterben ließ, und zu Ihm ist die Auferstehung.“ – der Schlaf als Zeichen (78:9).", quelle: "Sahih al-Buchari, Nr. 6312"}
],
hanafi: null,
umsetzung: [
 "Lerne die Schlaf- und Aufwach-Duʿā (Buchari 6312) auswendig – damit machst du das Zeichen aus 78:9 jeden Abend und jeden Morgen zum bewussten Gedenken.",
 "Mach die Neun-Zeichen-Übung: Gehe die Liste 78:6–16 einmal ruhig durch und danke für jedes einzelne Zeichen konkret (dein Bett, dein Schlaf, das Licht, das Wasser, das Brot).",
 "Begegne Diskussionen über Glaubensfragen nach der Methode der Sure: Stelle Fragen, die der andere aus eigener Erfahrung beantworten kann, statt zu streiten.",
 "Prüfe dein Verhalten gegenüber Menschen, die schwächer sind als du – wenn sogar zwischen Tieren abgerechnet wird, wird zwischen dir und ihnen nichts vergessen. Gib heute ein Recht zurück, das du jemandem schuldest."
]
},

// ───────────────────────── Lektion 81: An-Nāziʿāt ─────────────────────────
{
sure: 79, offb: 81, name: "An-Nāziʿāt", arab: "سُورَةُ النَّازِعَاتِ", de: "Die Entreißenden", verse: 46, ort: "Mekka",
zeit: "Spätmekkanisch – über Tod, Auferstehung und das Muster des Tyrannen, verkörpert in Pharao",
kurz: "Die Sure beginnt mit fünf Schwüren bei den Engeln: bei denen, die die Seelen der Ungläubigen hart entreißen, und denen, die die Seelen der Gläubigen sanft lösen. Dann der doppelte Stoß der Auferstehung und die zweifelnde Frage der Mekkaner: „Sollen wir etwa, wenn wir morsche Knochen sind, zurückgebracht werden?“ Als Antwort erzählt die Sure kurz die Geschichte Mūsās: Am Ort Ṭuwā erhält er den Auftrag, zu Pharao zu gehen und ihn mit einer sanften Frage einzuladen: „Möchtest du dich läutern?“ Pharao lehnt ab und ruft: „Ich bin euer höchster Herr!“ – und wird zum warnenden Beispiel. Dann zeigt die Sure Allahs Schöpfung von Himmel und Erde und schließt mit der wichtigsten Regel der Tazkiya: „Wer die Stellung seines Herrn fürchtet und die Seele von der Begierde abhält – das Paradies ist die Heimstatt.“",
schluessel: {arab: "وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَىٰ ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَىٰ", ueb: "Was aber den angeht, der die Stellung seines Herrn fürchtet und die Seele von der Begierde abhält – das Paradies ist die Heimstatt.", ref: "79:40–41"},
kontext: ["Die Sure steht in einer Reihe mit Al-Qiyāma, Al-Mursalāt und An-Nabaʾ: Immer wieder geht es um die Auferstehung, weil sie der zentrale Streitpunkt Mekkas war. Neu ist hier die Verbindung von zwei Bildern: dem Tod des Einzelnen (die Engel, die die Seele herausziehen) und der Geschichte eines Herrschers, der sich selbst zum Gott erklärte.",
"Die Mūsā-Episode ist besonders für das Verständnis von Daʿwa wichtig: Allah schickt Mūsā zum größten Tyrannen seiner Zeit, aber die Einladung beginnt nicht mit einer Drohung, sondern mit einer Frage: „Hast du nicht Lust, dich zu läutern (an tazakkā)?“ (79:18). In 20:44 heißt es ausdrücklich: „Sprecht zu ihm mit sanftem Wort.“ Wenn schon Pharao sanft angesprochen werden soll, wie viel mehr deine Familie und deine Freunde.",
"Die Sure endet mit einer Frage, die bis heute oft gestellt wird: „Sie fragen dich nach der Stunde, wann sie eintritt. Was hast du mit ihrer Erwähnung zu tun? Bei deinem Herrn liegt ihr Endpunkt“ (79:42–44). Der Prophet ﷺ war Warner, nicht Terminverkünder. Wer Daten für das Weltende berechnet, verlässt den Weg der Sunna."],
asbab: ["Für die Sure ist kein sahih gesicherter Einzelanlass überliefert. Zu 79:42 berichten die Tafsir-Werke, dass die Mekkaner den Propheten ﷺ immer wieder spöttisch nach dem Zeitpunkt der Stunde fragten (aṭ-Ṭabarī, Ibn Kathīr)."],
begriffe: [
 {arab: "النَّازِعَات", tr: "an-nāziʿāt", wurzel: "n-z-ʿ", erkl: "„Die Entreißenden“ – nach der Mehrheit die Engel, die die Seelen der Ungläubigen hart herausziehen; im Gegensatz dazu die nāschiṭāt, die die Seelen der Gläubigen sanft lösen (79:2). Dein Tod hat zwei mögliche Gesichter."},
 {arab: "الطَّامَّةُ الْكُبْرَىٰ", tr: "aṭ-ṭāmma al-kubrā", wurzel: "ṭ-m-m", erkl: "„Das größte überwältigende Ereignis“ (79:34) – ṭāmma ist das, was alles überflutet und übertönt. Ein weiterer Name des Jüngsten Tages (vgl. die Namen in Lektion 30)."},
 {arab: "تَزَكَّىٰ", tr: "tazakkā", wurzel: "z-k-w", erkl: "„Sich läutern“ (79:18) – die Einladung an Pharao. Dieselbe Wurzel wie 87:14 (Lektion 8) und 91:9 (Lektion 26). Selbst dem Tyrannen wird zuerst Tazkiya angeboten, nicht Strafe."},
 {arab: "أَنَا رَبُّكُمُ الْأَعْلَىٰ", tr: "ana rabbukumu l-aʿlā", wurzel: "ʿ-l-w", erkl: "„Ich bin euer höchster Herr“ (79:24) – Pharaos Anmaßung. Beachte den Kontrast zu 87:1 „Preise den Namen deines höchsten Herrn“ (Lektion 8): Den Titel al-aʿlā beansprucht ein Mensch, und er endet als Lehrbeispiel."},
 {arab: "دَحَاهَا", tr: "daḥāhā", wurzel: "d-ḥ-w", erkl: "„Er hat sie ausgebreitet“ (79:30) – die Erde, bewohnbar gemacht mit Wasser, Weide und festen Bergen „als Nießbrauch für euch und euer Vieh“. Schöpfung als Vorbereitung eines Wohnorts."},
 {arab: "الْهَوَىٰ", tr: "al-hawā", wurzel: "h-w-y", erkl: "Die Begierde, die Neigung der Seele – dieselbe Wurzel wie hāwiya, der Abgrund (Lektion 30), und wie in 53:3 (Lektion 23). Die Seele von der Begierde abzuhalten ist nach 79:40 die Tür zum Paradies."}
],
tafsir: [
 {vers: "Verse 1–14", text: "Fünf Schwüre bei Engeln mit ihren Aufgaben: entreißen, lösen, schwimmend gleiten, vorauseilen, die Angelegenheit lenken. Dann: „Am Tag, an dem das Beben bebt und ihm das Folgende folgt – Herzen an jenem Tag sind voller Angst, ihre Blicke gesenkt.“ Die Leugner fragen: „Sollen wir etwa in den früheren Zustand zurückgebracht werden, wenn wir morsche Knochen sind? Das wäre dann eine verlustreiche Rückkehr!“ Allah antwortet: „Es ist nur ein einziger Schrei, und schon sind sie auf der Erdoberfläche.“ Ibn Kathīr: Was die Menschen für schwer halten, ist für Allah ein einziger Ruf (vgl. kun fa-yakūn, Lektion 41)."},
 {vers: "Verse 15–26", text: "„Ist die Geschichte Mūsās zu dir gekommen?“ Sein Herr ruft ihn im heiligen Tal Ṭuwā: „Geh zu Pharao, denn er hat die Grenzen überschritten. Und sag: Möchtest du dich läutern? Und dass ich dich zu deinem Herrn leite, damit du (Ihn) fürchtest?“ Mūsā zeigt das größte Zeichen, Pharao leugnet, wendet sich ab, versammelt sein Volk und ruft: „Ich bin euer höchster Herr!“ – „Da ergriff ihn Allah mit der Strafe des Jenseits und des Diesseits.“ As-Saʿdī: Die Reihenfolge der Einladung ist bemerkenswert – zuerst Läuterung, dann Erkenntnis Allahs, dann Gottesfurcht. Wer Allah kennt, fürchtet Ihn; wer sich nicht läutern lässt, erkennt Ihn nicht. „Darin ist wahrlich eine Lehre für den, der (Allah) fürchtet.“"},
 {vers: "Verse 27–33", text: "„Seid ihr etwa schwerer zu erschaffen oder der Himmel? Er hat ihn gebaut.“ Allah erhob seine Decke, ordnete ihn, verdunkelte seine Nacht und ließ seinen Morgen hervortreten; danach breitete Er die Erde aus, ließ ihr Wasser und ihre Weide hervorkommen und festigte die Berge – „als Nießbrauch für euch und euer Vieh“. Al-Qurṭubī: Das Argument ist eine Verhältnisrechnung – wer das Größere (Himmel und Erde) erschaffen hat, für den ist das Kleinere (deine Auferweckung) kein Problem (vgl. 40:57)."},
 {vers: "Verse 34–46", text: "„Wenn dann das größte überwältigende Ereignis kommt, an dem Tag, an dem sich der Mensch an das erinnert, worum er sich bemühte, und die Hölle für jeden sichtbar gemacht wird …“ Dann die zwei Wege in vier Versen: „Was den angeht, der das Maß überschritt und das diesseitige Leben vorzog – die Hölle ist die Heimstatt. Was aber den angeht, der die Stellung seines Herrn fürchtete und die Seele von der Begierde abhielt – das Paradies ist die Heimstatt.“ Ibn Kathīr: Die Stellung des Herrn fürchten heißt, sich bewusst zu machen, dass man vor Allah stehen wird. Diese Furcht ist die Bremse der Begierde. Die Schlussverse: Die Frage nach der Stunde gehört nicht zum Auftrag des Propheten ﷺ; „du bist nur ein Warner für den, der sie fürchtet“, und an jenem Tag wird es den Menschen vorkommen, „als hätten sie nur einen Abend oder seinen Morgen verweilt“."}
],
ahadith: [
 {text: "„Das Paradies ist umgeben von Unangenehmem, und das Feuer ist umgeben von Begierden.“ – der Kommentar zu 79:40–41.", quelle: "Sahih al-Buchari, Nr. 6487; Sahih Muslim, Nr. 2822"},
 {text: "„Ich und die Stunde wurden gesandt wie diese beiden“ – und er legte Zeige- und Mittelfinger nebeneinander.", quelle: "Sahih al-Buchari, Nr. 6504; Sahih Muslim, Nr. 2951"},
 {text: "Der lange Hadith des al-Barāʾ ibn ʿĀzib über das Sterben des Gläubigen, dessen Seele herausfließt „wie ein Tropfen aus dem Wasserschlauch“, und des Ungläubigen, dessen Seele herausgezerrt wird – die Erklärung von 79:1–2.", quelle: "Sunan Abū Dāwūd, Nr. 4753; Musnad Aḥmad, Nr. 18534; von al-Albānī als sahih eingestuft"}
],
hanafi: null,
umsetzung: [
 "Präge dir 79:40–41 als Notfall-Vers ein: Wenn eine Begierde dich zieht, sprich innerlich „die Stellung meines Herrn“ – und stell dir den Moment vor, an dem du vor Ihm stehst.",
 "Übe die Mūsā-Methode in deinen Gesprächen: Lade zuerst mit einer sanften Frage ein, bevor du kritisierst. „Möchtest du nicht …?“ öffnet mehr Türen als „Du musst …“.",
 "Überprüfe deine eigenen kleinen „Ich bin der Höchste“-Momente: Wo willst du das letzte Wort haben, Recht behalten, über anderen stehen? Der Tyrann im Großen beginnt als Ego im Kleinen.",
 "Halte dich fern von Endzeit-Spekulationen und Datumsberechnungen; konzentriere dich wie die Sure auf die Vorbereitung, nicht auf den Termin."
]
},

// ───────────────────────── Lektion 82: Al-Infiṭār ─────────────────────────
{
sure: 82, offb: 82, name: "Al-Infiṭār", arab: "سُورَةُ الِانفِطَارِ", de: "Das Zerbrechen", verse: 19, ort: "Mekka",
zeit: "Spätmekkanisch – die Schwestersure von At-Takwīr, mit der zärtlichsten und schärfsten Frage des Korans",
kurz: "Wenn der Himmel zerbricht, die Sterne sich zerstreuen, die Meere ineinander fließen und die Gräber umgewühlt werden, dann weiß jede Seele, was sie vorausgeschickt und was sie zurückgelassen hat. Dann kommt die Frage, über die Gelehrte jahrhundertelang geweint haben: „O Mensch, was hat dich hinsichtlich deines edelmütigen Herrn getäuscht – Der dich erschaffen, zurechtgeformt und ebenmäßig gemacht hat, in welcher Gestalt auch immer Er wollte, hat Er dich zusammengefügt?“ Allah nennt sich hier ar-Karīm, der Edelmütige – und gerade Seine Großzügigkeit ist es, die der Mensch ausnutzt. Über jedem stehen edle Schreiber, die alles wissen, was ihr tut. Die Guten sind in Wonne, die Sittenlosen im Feuer. Und am Ende: An jenem Tag vermag keine Seele etwas für eine andere – „der Befehl an jenem Tag gehört Allah“.",
schluessel: {arab: "يَا أَيُّهَا الْإِنسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ", ueb: "O Mensch, was hat dich hinsichtlich deines edelmütigen Herrn getäuscht?", ref: "82:6"},
kontext: ["Die Sure gehört zu den drei Suren, die der Prophet ﷺ für jeden empfahl, der den Tag der Auferstehung „wie mit eigenen Augen“ sehen will: At-Takwīr (Lektion 7), Al-Infiṭār und Al-Inschiqāq (Sunan at-Tirmidhī, Nr. 3333). Alle drei beginnen mit dem Zerbrechen der Welt und lenken dann den Blick auf den Einzelnen.",
"Die Frage in 82:6 ist berühmt, weil sie ungewöhnlich ist: Allah fragt nicht „Was hat dich gegen deinen strengen Herrn aufgebracht?“, sondern „Was hat dich hinsichtlich deines edelmütigen Herrn getäuscht?“ Die Gelehrten haben dazu viel gesagt. Manche meinten, die Frage enthalte schon den Hinweis auf die Antwort: Es ist gerade Allahs Edelmut, Seine Geduld und Sein Verdecken der Sünden, die den Menschen nachlässig machen. ʿUmar soll gesagt haben: „Seine Unwissenheit hat ihn getäuscht.“ Die Frage ist Tadel und Einladung zugleich.",
"Die Verse 10–12 nennen die Schreiber-Engel kirām kātibīn, die „edlen Schreibenden“. Sie ergänzen das Bild aus Qāf (raqīb ʿatīd, Lektion 34) und Aṭ-Ṭāriq (ḥāfiẓ, Lektion 36). Die Aufzeichnung geschieht nicht durch feindliche Beobachter, sondern durch edle Wesen – und nach dem Hadith zu Gunsten des Gläubigen großzügig: Eine beabsichtigte gute Tat wird schon gutgeschrieben, eine beabsichtigte schlechte nicht."],
asbab: ["Für die Sure ist kein Einzelanlass überliefert. Manche Tafsir-Werke nennen einen Mann aus Mekka, der den Propheten ﷺ verhöhnte, als Anlass von 82:6; diese Berichte sind nicht gesichert, und der Wortlaut richtet sich an jeden Menschen."],
begriffe: [
 {arab: "انفَطَرَتْ", tr: "infaṭarat", wurzel: "f-ṭ-r", erkl: "„Zerbrochen/gespalten“ (82:1) – dieselbe Wurzel wie fiṭra (Lektion 39) und Fāṭir (Erschaffer): Der Himmel, der am Anfang „erschaffen“ (faṭara) wurde, wird am Ende „aufgebrochen“. Anfang und Ende tragen dieselbe Wurzel."},
 {arab: "غَرَّكَ", tr: "ġarraka", wurzel: "ġ-r-r", erkl: "„Hat dich getäuscht“ – davon ġurūr (Täuschung) und al-ġarūr (der Täuscher, der Satan, 31:33). Der Mensch lässt sich von Allahs Geduld täuschen und hält Aufschub für Freispruch."},
 {arab: "الْكَرِيم", tr: "al-Karīm", wurzel: "k-r-m", erkl: "„Der Edelmütige, Großzügige“ – Der gibt, ohne dass man es verdient, und verdeckt, ohne dass man es merkt. Dass dieser Name in der Tadelfrage steht, ist der Kern der Sure: Großzügigkeit soll Dankbarkeit wecken, nicht Nachlässigkeit."},
 {arab: "فَعَدَلَكَ", tr: "fa-ʿadalaka", wurzel: "ʿ-d-l", erkl: "„Und hat dich ebenmäßig gemacht“ (82:7) – ʿadl: Gleichgewicht, Gerechtigkeit. Dein Körper ist ausgewogen gebaut, die beiden Seiten passen zueinander. Vgl. aḥsan taqwīm in At-Tīn (Lektion 28)."},
 {arab: "كِرَامًا كَاتِبِينَ", tr: "kirāman kātibīn", wurzel: "k-r-m / k-t-b", erkl: "„Edle Schreibende“ (82:11) – die Engel, die die Taten aufzeichnen. Edel, weil sie nichts verfälschen, nichts übertreiben und nichts verschweigen."},
 {arab: "الْأَبْرَار / الْفُجَّار", tr: "al-abrār / al-fudschdschār", wurzel: "b-r-r / f-dsch-r", erkl: "Die Gütigen (von birr, umfassende Güte, vgl. 60:8 in den Brennpunkten) und die Sittenlosen (von fudschūr, vgl. 91:8 in Lektion 26). Die Menschheit am Ende in zwei Gruppen – benannt nach ihrem Charakter."}
],
tafsir: [
 {vers: "Verse 1–5", text: "Vier Bilder des Weltendes: Der Himmel bricht, die Sterne zerstreuen sich, die Meere fließen ineinander (fudschdschirat, „aufgerissen werden“), die Gräber werden umgewühlt. „… dann weiß jede Seele, was sie vorausgeschickt und was sie zurückgelassen hat.“ Ibn Kathīr: Was sie vorausgeschickt hat, sind ihre Taten; was sie zurückgelassen hat, sind die guten oder schlechten Gewohnheiten, die nach ihr weiterwirken (vgl. āthār in 36:12, Lektion 41)."},
 {vers: "Verse 6–12", text: "„O Mensch, was hat dich hinsichtlich deines edelmütigen Herrn getäuscht, Der dich erschaffen und dann zurechtgeformt und ebenmäßig gemacht hat, in welcher Gestalt Er wollte, hat Er dich zusammengefügt?“ Al-Qurṭubī: Die Frage erinnert den Menschen an das, was er Allah verdankt – Existenz, Gestalt, Gleichgewicht – und fragt dann, wie er so leben kann, als schulde er nichts. „Keineswegs! Vielmehr erklärt ihr das Gericht für Lüge.“ Das ist die eigentliche Ursache: nicht die Großzügigkeit Allahs, sondern das Leugnen der Abrechnung. „Über euch sind wahrlich Hüter, edle Schreibende, die wissen, was ihr tut.“"},
 {vers: "Verse 13–19", text: "„Die Gütigen sind in Wonne, und die Sittenlosen sind in einem Höllenbrand, in dem sie am Tag des Gerichts brennen, und sie werden ihm nicht entgehen.“ Dann zweimal die Frage „Und was lässt dich wissen, was der Tag des Gerichts ist?“ und die Antwort: „Der Tag, an dem keine Seele für eine andere etwas vermag, und der Befehl an jenem Tag gehört Allah.“ As-Saʿdī: Im Diesseits haben Menschen eine gewisse Macht über andere – Eltern, Herrscher, Freunde. An jenem Tag fällt jede menschliche Macht weg. Darum: Suche heute Schutz bei Dem, Dem dann allein der Befehl gehört."}
],
ahadith: [
 {text: "„Wer sich freuen würde, den Tag der Auferstehung zu sehen, als sähe er ihn mit eigenen Augen, der lese: Idhā sch-schamsu kuwwirat, Idhā s-samāʾu nfaṭarat und Idhā s-samāʾu nschaqqat.“", quelle: "Sunan at-Tirmidhī, Nr. 3333; hasan"},
 {text: "Hadith Qudsi: Wer eine gute Tat beabsichtigt und sie nicht ausführt, dem schreibt Allah eine vollständige gute Tat; führt er sie aus, zehnfach bis siebenhundertfach. Wer eine schlechte Tat beabsichtigt und sie nicht ausführt, dem schreibt Er eine gute Tat; führt er sie aus, eine einzige schlechte.", quelle: "Sahih al-Buchari, Nr. 6491; Sahih Muslim, Nr. 131"},
 {text: "„Fürchte Allah, wo immer du bist, lass auf die schlechte Tat eine gute folgen, die sie auslöscht, und behandle die Menschen mit gutem Charakter.“", quelle: "Sunan at-Tirmidhī, Nr. 1987; hasan"}
],
hanafi: null,
umsetzung: [
 "Stelle dir 82:6 einmal am Tag persönlich: „Was hat mich heute hinsichtlich meines edelmütigen Herrn getäuscht?“ – und antworte ehrlich in einem Satz.",
 "Nutze die Großzügigkeit der Schreiber (Buchari 6491): Fasse jeden Morgen mehrere gute Absichten (Sadaqa, Besuch, Koranlesen). Schon die Absicht wird gutgeschrieben.",
 "Wende Tirmidhī 1987 an: Lass auf jeden Fehltritt sofort eine gute Tat folgen – zwei Rakʿa, eine Spende, ein freundliches Wort.",
 "Erinnere dich bei Machtgefühlen über andere (Eltern über Kinder, Chef über Mitarbeiter) an 82:19: An jenem Tag gehört der Befehl allein Allah."
]
},

// ───────────────────────── Lektion 83: Al-Inschiqāq ─────────────────────────
{
sure: 84, offb: 83, name: "Al-Inschiqāq", arab: "سُورَةُ الِانشِقَاقِ", de: "Das Zerreißen", verse: 25, ort: "Mekka",
zeit: "Spätmekkanisch – die dritte der drei Weltende-Suren, mit dem Bild des menschlichen Lebens als Reise zu Allah",
kurz: "Der Himmel zerreißt und gehorcht seinem Herrn, die Erde wird ausgebreitet, wirft aus, was in ihr ist, und gehorcht ebenfalls. Dann wendet sich die Sure an dich: „O Mensch, du mühst dich ab zu deinem Herrn hin, und du wirst Ihm begegnen.“ Das ganze Leben ist ein Weg mit einem festen Ziel. Wer sein Buch in die rechte Hand bekommt, erhält eine leichte Abrechnung und kehrt froh zu den Seinen zurück; wer es hinter seinem Rücken bekommt, ruft nach Vernichtung – er war im Diesseits fröhlich in seiner Familie und meinte, er würde nie zurückkehren. Dann schwört Allah bei der Abendröte, der Nacht und dem vollen Mond: „Ihr werdet gewiss Stufe um Stufe durchlaufen.“ Und die Sure fragt: Warum werfen sie sich nicht nieder, wenn ihnen der Koran vorgelesen wird? – Hier ist eine Niederwerfungsstelle (84:21).",
schluessel: {arab: "يَا أَيُّهَا الْإِنسَانُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَاقِيهِ", ueb: "O Mensch, du mühst dich ab zu deinem Herrn hin, und du wirst Ihm begegnen.", ref: "84:6"},
kontext: ["Al-Inschiqāq ist die dritte der Suren, die der Prophet ﷺ für das „Sehen“ des Jüngsten Tages empfahl (Sunan at-Tirmidhī, Nr. 3333; vgl. Lektion 7 und 82). Sie fügt ein neues Bild hinzu: Himmel und Erde „hören“ auf ihren Herrn und tun, was ihnen geboten ist (adhinat). Die Schöpfung gehorcht – nur der Mensch hat die Wahl.",
"Vers 6 ist einer der schönsten Lebens-Verse des Korans. Kadḥ bedeutet harte, anstrengende Arbeit, die Spuren hinterlässt. Jeder Mensch arbeitet sich durch sein Leben – der Gläubige wie der Ungläubige. Der Unterschied liegt nicht in der Mühe, sondern im Bewusstsein des Ziels: „zu deinem Herrn hin … und du wirst Ihm begegnen“. Vergleiche das mit kabad, der Mühsal in 90:4 (Lektion 35).",
"Die Sure enthält eine Tilāwa-Sadschda in Vers 21. Abū Rāfiʿ berichtet, dass Abū Huraira im ʿIschāʾ-Gebet diese Sure rezitierte und sich niederwarf; auf Nachfrage sagte er: „Ich habe mich hinter Abū l-Qāsim ﷺ dabei niedergeworfen und werde es tun, bis ich ihm begegne“ (Sahih al-Buchari, Nr. 766; Sahih Muslim, Nr. 578)."],
asbab: ["Für die Sure ist kein spezifischer Offenbarungsanlass überliefert. Zur Praxis der Sadschda bei 84:21 siehe den Bericht Abū Hurairas (Sahih al-Buchari, Nr. 766; Sahih Muslim, Nr. 578)."],
begriffe: [
 {arab: "أَذِنَتْ", tr: "adhinat", wurzel: "ʾ-dh-n", erkl: "„Sie hörte (gehorsam)“ (84:2, 84:5) – von udhun, Ohr: Himmel und Erde „hören“ auf ihren Herrn und befolgen Seinen Befehl. Gehorsam als Hören – das ist auch die Haltung des Gläubigen: samiʿnā wa-aṭaʿnā (2:285)."},
 {arab: "كَادِح", tr: "kādiḥ", wurzel: "k-d-ḥ", erkl: "„Einer, der sich abmüht“ – kadḥ ist Arbeit, die anstrengt und Spuren hinterlässt (wie Schrammen auf der Haut). Dein ganzes Leben ist kadḥ – die Frage ist nur, ob es „zu deinem Herrn hin“ geht."},
 {arab: "حِسَابًا يَسِيرًا", tr: "ḥisāban yasīrā", wurzel: "y-s-r", erkl: "„Eine leichte Abrechnung“ (84:8) – nach dem Hadith ʿĀʾischas das bloße Vorlegen der Taten ohne genaue Untersuchung (ʿarḍ). Wer genau befragt wird, ist verloren; Allahs Barmherzigkeit zeigt sich darin, dass Er beim Gläubigen nicht nachbohrt."},
 {arab: "وَرَاءَ ظَهْرِهِ", tr: "warāʾa ẓahrih", wurzel: "ẓ-h-r", erkl: "„Hinter seinem Rücken“ (84:10) – wer das Buch Allahs im Leben hinter seinen Rücken warf, bekommt sein eigenes Buch hinter den Rücken. Die Strafe spiegelt das Verhalten."},
 {arab: "الشَّفَق", tr: "asch-schafaq", wurzel: "sch-f-q", erkl: "Die Abendröte (84:16) – das Licht nach Sonnenuntergang. Nach ihr richtet sich der Beginn des ʿIschāʾ-Gebets; darüber gibt es eine bekannte Fiqh-Diskussion (siehe hanafitischer Hinweis)."},
 {arab: "طَبَقًا عَن طَبَقٍ", tr: "ṭabaqan ʿan ṭabaq", wurzel: "ṭ-b-q", erkl: "„Stufe um Stufe“ (84:19) – vom Tropfen zum Kind, vom Kind zum Erwachsenen, vom Leben zum Tod, vom Grab zur Auferstehung, von dort zum Endziel. Nach Ibn ʿAbbās auch: Zustand nach Zustand. Das Leben ist eine Treppe, keine Ebene."}
],
tafsir: [
 {vers: "Verse 1–6", text: "„Wenn der Himmel zerreißt und auf seinen Herrn hört, wie es ihm gebührt, und wenn die Erde ausgedehnt wird, auswirft, was in ihr ist, und sich leert und auf ihren Herrn hört …“ Dann ohne Hauptsatz der Wechsel zum Menschen: „O Mensch, du mühst dich ab zu deinem Herrn hin, und du wirst Ihm begegnen.“ Ibn Kathīr: Was du tust, gut oder schlecht, wirst du bei Allah wiederfinden. As-Saʿdī: Der Vers lädt ein, die Mühe des Lebens bewusst auf Allah auszurichten – dieselbe Arbeit, dieselbe Familie, dieselbe Anstrengung, aber mit Ziel."},
 {vers: "Verse 7–15", text: "Die zwei Bücher: Wer sein Buch in seine Rechte bekommt, „wird eine leichte Abrechnung erhalten und froh zu seinen Angehörigen zurückkehren“. Wer es hinter seinem Rücken bekommt, „wird nach Vernichtung rufen und in einem Feuer brennen. Er war ja unter seinen Angehörigen fröhlich; er meinte, er würde nie zurückkehren.“ Al-Qurṭubī: Die Freude im Diesseits wird nicht verurteilt, sondern die Freude, die das Jenseits vergisst. Der Gläubige freut sich im Jenseits mit seiner Familie, der Leugner hatte seine einzige Freude schon im Diesseits. „Doch! Sein Herr sah ihn wohl.“"},
 {vers: "Verse 16–25", text: "Schwur bei der Abendröte, der Nacht und dem, was sie zusammentreibt, und dem Mond, wenn er voll wird: „Ihr werdet gewiss Stufe um Stufe durchlaufen.“ Dann die Frage: „Was ist mit ihnen, dass sie nicht glauben, und wenn ihnen der Koran vorgelesen wird, werfen sie sich nicht nieder?“ Ibn Kathīr: Die Sadschda ist hier die natürliche Antwort auf das Hören des Korans. „Allah weiß am besten, was sie in sich verbergen“ – vgl. die geprüften Geheimnisse in 86:9 (Lektion 36). Schluss: Für die Glaubenden ist „ein Lohn, der nicht abreißt“ (ġairu mamnūn, vgl. Lektion 28)."}
],
ahadith: [
 {text: "ʿĀʾischa: Der Prophet ﷺ sagte: „Wer bei der Abrechnung genau befragt wird, wird bestraft.“ Ich sagte: „Sagt Allah nicht: ‚Er wird eine leichte Abrechnung erhalten‘?“ Er sagte: „Das ist nur das Vorlegen (al-ʿarḍ).“", quelle: "Sahih al-Buchari, Nr. 103 und 4939; Sahih Muslim, Nr. 2876"},
 {text: "Abū Huraira rezitierte im ʿIschāʾ-Gebet „Idhā s-samāʾu nschaqqat“ und warf sich nieder: „Ich habe mich hinter Abū l-Qāsim ﷺ dabei niedergeworfen und werde mich weiter dabei niederwerfen, bis ich ihm begegne.“", quelle: "Sahih al-Buchari, Nr. 766; Sahih Muslim, Nr. 578"},
 {text: "„Wer sich freuen würde, den Tag der Auferstehung zu sehen … der lese … Idhā s-samāʾu nschaqqat.“", quelle: "Sunan at-Tirmidhī, Nr. 3333; hasan"}
],
hanafi: "Vers 84:21 ist nach hanafitischer Schule eine der 14 Tilāwa-Sadschdas, und die Niederwerfung ist wādschib für den, der den Vers rezitiert oder hört – im Gebet wie außerhalb. Hier gibt es einen echten Schulunterschied: Nach der verbreiteten mālikitischen Position gehören die Sadschdas der kurzen Suren (Mufaṣṣal), darunter 84:21, nicht zu den festen Niederwerfungsstellen; die Hanafiten folgen dagegen dem Bericht Abū Hurairas (Buchari 766). Praktische hanafitische Regel im Gebet: Wer den Vers rezitiert und gleich danach (nach höchstens etwa drei Versen) in Rukūʿ und Sudschūd geht, dem gilt die Tilāwa-Sadschda nach der Schule durch die Niederwerfung des Gebets als erfüllt; sonst macht er eine eigene Niederwerfung. Zur Abendröte (84:16): Nach Abū Ḥanīfa beginnt ʿIschāʾ erst, wenn auch die weiße Dämmerung verschwunden ist; nach seinen Schülern Abū Yūsuf und Muḥammad (und der Mehrheit) schon nach dem Verschwinden der roten Abendröte – viele spätere Hanafiten folgen in der Fatwa den beiden Schülern.",
umsetzung: [
 "Mach 84:6 zu deinem Arbeitsvers: Sprich vor der Arbeit innerlich „zu meinem Herrn hin“ – und gib deiner Mühe damit eine Richtung.",
 "Ergänze deine Sadschda-Liste: 84:21 ist hanafitisch wādschib. Du kennst jetzt 7:206, 38:24, 53:62, 84:21 und 96:19.",
 "Bitte regelmäßig um eine leichte Abrechnung: Allāhumma ḥāsibnī ḥisāban yasīrā (diese Duʿā ist von ʿĀʾischa als Gebet des Propheten ﷺ überliefert, Musnad Aḥmad; sinngemäß).",
 "Prüfe deine Freude: Freust du dich mit deiner Familie so, dass ihr euch auch im Jenseits wiedersehen wollt? Plane eine gemeinsame gute Tat als Familie (Spende, Besuch, Koranabend)."
]
},

// ───────────────────────── Lektion 84: Ar-Rūm ─────────────────────────
{
sure: 30, offb: 84, name: "Ar-Rūm", arab: "سُورَةُ الرُّومِ", de: "Die Römer", verse: 60, ort: "Mekka",
zeit: "Spätmekkanisch, um 615 n. Chr. – nach der Niederlage der Byzantiner gegen die Perser; mit einer Vorhersage, die sich wenige Jahre später erfüllte",
kurz: "Die Byzantiner (Rūm) waren von den Perser vernichtend geschlagen worden; Jerusalem war gefallen. Die Götzendiener Mekkas freuten sich, denn sie fühlten sich den feuerverehrenden Persern näher; die Muslime waren traurig, denn die Byzantiner waren Schriftbesitzer. Da kam die Sure mit einer erstaunlichen Ansage: „Die Römer sind besiegt worden im nächstgelegenen Land. Doch nach ihrer Niederlage werden sie siegen – in wenigen Jahren.“ Abū Bakr ging sogar eine Wette darüber ein. Die Vorhersage erfüllte sich. Danach öffnet die Sure ein Album der Zeichen Allahs: Erschaffung aus Erde, Ehe als Ort der Ruhe mit Liebe und Barmherzigkeit (30:21), die Vielfalt der Sprachen und Hautfarben, Schlaf, Blitz, Regen. Im Zentrum steht die fiṭra (30:30): „Richte dein Gesicht auf die Religion als Aufrichtiger – die natürliche Anlage Allahs, nach der Er die Menschen erschaffen hat.“",
schluessel: {arab: "وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَاجًا لِّتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً", ueb: "Und zu Seinen Zeichen gehört, dass Er euch aus euch selbst Gattinnen erschaffen hat, damit ihr bei ihnen Ruhe findet, und Er hat zwischen euch Zuneigung und Barmherzigkeit gesetzt.", ref: "30:21"},
kontext: ["Um 614 n. Chr. eroberten die Sassaniden (Perser) Jerusalem und entrissen den Byzantinern große Gebiete in Syrien und Palästina – „im nächstgelegenen Land“ (fī adnā l-arḍ), nahe an Arabien. Für die Mekkaner war das ein Zeichen: So wie die Perser die Schriftbesitzer besiegt haben, werden wir die Muslime besiegen. Die Sure widerspricht öffentlich und gibt einen Zeitrahmen von biḍʿ sinīn – einer Anzahl von drei bis neun Jahren.",
"Ibn ʿAbbās berichtet: Abū Bakr wettete mit den Götzendienern (vor dem Verbot des Glücksspiels) über den Ausgang. Der Prophet ﷺ riet ihm, den Zeitrahmen auf die ganze Spanne von biḍʿ auszudehnen. Innerhalb dieser Frist siegten die Byzantiner unter Herakleios (ab ca. 622–624), und die Muslime freuten sich – nach verbreiteten Berichten traf die Nachricht etwa um die Zeit von Badr ein, als die Muslime selbst über die Quraisch siegten: „An jenem Tag werden sich die Gläubigen freuen über Allahs Hilfe“ (30:4–5; Sunan at-Tirmidhī, Nr. 3193). Eine politische Vorhersage mit Datum – überprüfbar und erfüllt.",
"Die Sure enthält auch eine wichtige Stufe der Gesetzgebung: Vers 39 erwähnt erstmals den Zins (ribā): „Was ihr an Zins gebt, damit es sich im Vermögen der Menschen vermehrt, vermehrt sich nicht bei Allah.“ Das ist noch kein Verbot, sondern eine moralische Weichenstellung – das endgültige Verbot kommt in Medina (3:130 und 2:275–281, siehe Lektion 87). So erzieht der Koran: erst das Herz, dann das Gesetz."],
asbab: [
 {text: "Verse 1–5: die Niederlage der Byzantiner, die Freude der Götzendiener, die Wette Abū Bakrs und die Erfüllung der Vorhersage.", quelle: "Sunan at-Tirmidhī, Nr. 3193 und 3194; von at-Tirmidhī als hasan sahih eingestuft"}
],
begriffe: [
 {arab: "الرُّوم", tr: "ar-Rūm", wurzel: "–", erkl: "Die „Römer“ – gemeint ist das Oströmische (Byzantinische) Reich mit der Hauptstadt Konstantinopel. Christliche Schriftbesitzer, deren Schicksal die Muslime näher bewegte als das der Perser."},
 {arab: "بِضْعِ سِنِينَ", tr: "biḍʿi sinīn", wurzel: "b-ḍ-ʿ", erkl: "„In einigen Jahren“ – biḍʿ bezeichnet im Arabischen eine Zahl zwischen drei und neun. Eine präzise, überprüfbare Ansage, die sich erfüllte."},
 {arab: "آيَات", tr: "āyāt", wurzel: "ʾ-y-y", erkl: "Zeichen – das Leitwort der Sure: Sechsmal heißt es „Und zu Seinen Zeichen gehört …“ (30:20–25). Jedes Zeichen ist ein Fenster: Durch die Schöpfung schaust du auf den Schöpfer (vgl. Lektion 41)."},
 {arab: "مَوَدَّة وَرَحْمَة", tr: "mawadda wa-raḥma", wurzel: "w-d-d / r-ḥ-m", erkl: "Zuneigung und Barmherzigkeit (30:21) – zwei Säulen der Ehe: mawadda ist die zeigende Liebe (dieselbe Wurzel wie al-Wadūd, Lektion 27), raḥma die Barmherzigkeit, die trägt, wenn die Gefühle schwächer werden, im Alter, in der Krankheit, im Streit."},
 {arab: "فِطْرَة", tr: "fiṭra", wurzel: "f-ṭ-r", erkl: "Die natürliche Anlage (30:30), mit der jeder Mensch erschaffen ist: die Hinwendung zu Allah, der Sinn für Wahrheit und Gut. „Es gibt keine Änderung der Schöpfung Allahs.“ Vgl. den Ur-Bund 7:172 in Lektion 39."},
 {arab: "الْفَسَاد", tr: "al-fasād", wurzel: "f-s-d", erkl: "Verderben (30:41): „Verderben ist auf dem Festland und im Meer erschienen wegen dessen, was die Hände der Menschen erworben haben.“ Ein Vers, den heute viele im Blick auf Umwelt und Gesellschaft lesen – der Mensch erntet die Folgen seines Tuns, „damit sie vielleicht umkehren“."},
 {arab: "رِبًا", tr: "ribā", wurzel: "r-b-w", erkl: "Zins/Wucher – wörtlich „Vermehrung“. 30:39 ist die erste Erwähnung: Zins vermehrt sich nicht bei Allah, Zakat schon. Der Anfang eines Weges, der in Medina zum vollständigen Verbot führt."}
],
tafsir: [
 {vers: "Verse 1–10", text: "Die Vorhersage über die Byzantiner. Dann ein wichtiger Satz über die Menschen: „Sie kennen nur die Außenseite des diesseitigen Lebens, aber gegenüber dem Jenseits sind sie achtlos“ (30:7). Ibn Kathīr: Sie sind Meister im Handel, im Bauen, im Rechnen – und blind für das, was nach dem Tod kommt. Al-Ḥasan al-Baṣrī soll gesagt haben, manche wüssten genau, wie viel ein Dirham wiegt, und könnten doch nicht richtig beten. Dann der Blick auf frühere Völker, die stärker waren und die Erde mehr bebauten – und dennoch untergingen."},
 {vers: "Verse 11–19", text: "Allah beginnt die Schöpfung und wiederholt sie. Am Tag der Stunde teilen sich die Menschen: Die Gläubigen werden in einem Garten erfreut, die Leugner zur Strafe gebracht. Dann der Tasbīḥ-Befehl: „So sei Allah gepriesen, wenn ihr den Abend erreicht und wenn ihr den Morgen erreicht – Ihm gehört das Lob in den Himmeln und auf der Erde – und am späten Nachmittag und wenn ihr den Mittag erreicht“ (30:17–18). Ibn ʿAbbās sah darin einen Hinweis auf die fünf Gebetszeiten. Und: „Er bringt das Lebendige aus dem Toten hervor … so werdet auch ihr hervorgebracht werden.“"},
 {vers: "Verse 20–27", text: "Das Album der Zeichen: (1) Erschaffung aus Erde – „dann seid ihr auf einmal Menschen, die sich ausbreiten“. (2) Ehepartner aus euch selbst, Ruhe, Zuneigung und Barmherzigkeit. (3) Himmel und Erde und die Verschiedenheit eurer Sprachen und Farben – „darin sind Zeichen für die Wissenden“. (4) Euer Schlaf bei Nacht und Tag und euer Trachten nach Seiner Huld. (5) Der Blitz, der Furcht und Hoffnung weckt, und der Regen, der die tote Erde belebt. (6) Himmel und Erde stehen durch Seinen Befehl. As-Saʿdī zu Vers 22: Die Vielfalt der Sprachen und Hautfarben ist ein Zeichen Allahs, kein Grund für Überheblichkeit – ein klarer Vers gegen jeden Rassismus (vgl. Iblīs' „Ich bin besser als er“, Lektion 38)."},
 {vers: "Verse 28–40", text: "Ein Gleichnis gegen den Götzendienst: Würdet ihr eure Sklaven zu gleichberechtigten Teilhabern an eurem Besitz machen? Nein – wie könnt ihr dann Allah Teilhaber aus Seinen Geschöpfen geben? Dann der Kernvers 30:30: „So richte dein Gesicht auf die Religion als Aufrichtiger (ḥanīf) – die fiṭra Allahs, nach der Er die Menschen erschaffen hat. Es gibt keine Änderung der Schöpfung Allahs. Das ist die beständige Religion.“ Ibn Kathīr verbindet ihn mit dem Hadith: Jedes Kind wird auf der fiṭra geboren (Sahih al-Buchari, Nr. 1358). Warnung vor Spaltung: „Gehört nicht zu denen, die ihre Religion zerspalten haben und zu Parteien geworden sind, jede Partei froh über das, was bei ihr ist“ (30:32). Dann die Rechte der Verwandten, der Armen und Reisenden und der Zins-Vers 30:39."},
 {vers: "Verse 41–53", text: "„Verderben ist auf dem Land und im Meer erschienen wegen dessen, was die Hände der Menschen erworben haben, damit Er sie einen Teil dessen kosten lässt, was sie getan haben – vielleicht kehren sie um.“ Al-Qurṭubī: Dürre, Seuchen und Unruhen werden hier als Folge menschlicher Sünden und als Ruf zur Umkehr gedeutet. Dann wieder die Winde und der Regen als Freudenboten und das Bild der Wiederbelebung: „Schau auf die Spuren von Allahs Barmherzigkeit, wie Er die Erde nach ihrem Tod lebendig macht.“ Und der Trost an den Propheten ﷺ: „Du kannst nicht die Toten hören lassen … du kannst nur die hören lassen, die an Unsere Zeichen glauben.“"},
 {vers: "Verse 54–60", text: "„Allah ist es, Der euch aus Schwäche erschaffen hat, dann nach der Schwäche Stärke gegeben hat, dann nach der Stärke Schwäche und graues Haar gemacht hat.“ Das ganze Leben in einem Satz: Schwäche – Stärke – Schwäche. As-Saʿdī: Wer das versteht, nutzt die Mitte. Am Ende schwören die Übeltäter, sie hätten nur eine Stunde verweilt. Schluss: „So sei geduldig; das Versprechen Allahs ist wahr, und lass dich nicht von denen verunsichern, die keine Gewissheit haben.“ Die Sure, die mit einer politischen Vorhersage begann, endet mit der Gewissheit, dass Allahs Versprechen immer eintrifft."}
],
ahadith: [
 {text: "Ibn ʿAbbās über die Vorhersage zum Sieg der Byzantiner und die Wette Abū Bakrs – „und die Römer siegten innerhalb dieser Frist“.", quelle: "Sunan at-Tirmidhī, Nr. 3193; hasan sahih"},
 {text: "„Jedes Neugeborene wird auf der fiṭra geboren; dann machen seine Eltern es zum Juden, Christen oder Magier …“ – und Abū Huraira rezitierte dazu 30:30.", quelle: "Sahih al-Buchari, Nr. 1358; Sahih Muslim, Nr. 2658"},
 {text: "„Ein gläubiger Mann soll eine gläubige Frau nicht hassen: Missfällt ihm an ihr eine Eigenschaft, so gefällt ihm eine andere.“ – raḥma in der Ehe (30:21).", quelle: "Sahih Muslim, Nr. 1469"},
 {text: "„Der Beste von euch ist der Beste zu seiner Familie, und ich bin der Beste von euch zu meiner Familie.“", quelle: "Sunan at-Tirmidhī, Nr. 3895; sahih"}
],
hanafi: "Zu den Gebetszeiten aus 30:17–18 gibt es hanafitische Besonderheiten, die du kennen solltest: (1) Beim Fadschr-Gebet ist es nach der Schule empfohlen, es zu verrichten, wenn es schon etwas hell geworden ist (isfār), gestützt auf den Hadith „Verrichtet das Fadschr im Hellen, denn das ist größer an Lohn“ (Sunan at-Tirmidhī, Nr. 154) – die anderen Schulen bevorzugen die frühe Dunkelheit (ġalas). (2) Die ʿAṣr-Zeit beginnt nach Abū Ḥanīfa, wenn der Schatten eines Gegenstands doppelt so lang ist wie er selbst (zuzüglich des Mittagsschattens); nach seinen Schülern und der Mehrheit schon bei einfacher Länge. Gebetszeiten-Apps bieten dafür meist eine Einstellung „Hanafi“ für ʿAṣr – prüfe deine. Zu 30:39: Der Zins wird hier noch nicht verboten; das hanafitische Ribā-Recht beruht auf den medinensischen Versen und Hadithen (siehe Lektion 87).",
umsetzung: [
 "Lies 30:21 mit deinem Ehepartner (oder als Ziel für die Zukunft) und frage: Wo fehlt bei uns sakan (Ruhe), wo mawadda (gezeigte Zuneigung), wo raḥma (tragende Barmherzigkeit)? Arbeite an der schwächsten.",
 "Übe Muslim 1469: Wenn dich an einem Menschen etwas stört, zähle bewusst eine gute Eigenschaft dazu auf, bevor du urteilst.",
 "Stelle in deiner Gebets-App die ʿAṣr-Berechnung auf „Hanafi“, wenn du hanafitisch praktizierst, und verrichte Fadschr bewusst im isfār.",
 "Begegne Rassismus und Herkunftsstolz mit 30:22: Sprachen und Farben sind Zeichen Allahs, keine Rangordnung. Korrigiere solche Sprüche in deinem Umfeld freundlich, aber klar.",
 "Halte 30:41 im Blick: Behandle die Schöpfung (Wasser, Essen, Natur) als anvertrautes Gut. Verschwendung und Zerstörung sind Teil des fasād, den der Vers beschreibt."
]
},

// ───────────────────────── Lektion 85: Al-ʿAnkabūt ─────────────────────────
{
sure: 29, offb: 85, name: "Al-ʿAnkabūt", arab: "سُورَةُ الْعَنْكَبُوتِ", de: "Die Spinne", verse: 69, ort: "Mekka",
zeit: "Spätmekkanisch – in der Zeit härtester Verfolgung, kurz vor der Hidschra (nach manchen Gelehrten sind die ersten Verse medinensisch)",
kurz: "„Meinen die Menschen, dass sie in Ruhe gelassen werden, nur weil sie sagen: Wir glauben – ohne geprüft zu werden?“ Mit dieser Frage beginnt die Sure der Prüfung. Glaube wird nicht durch Worte bewiesen, sondern durch Standhaftigkeit. Die Sure zeigt Prüfungen aller Art: den Druck einer Mutter auf ihren Sohn, die 950 Jahre Nūḥs, das Feuer Ibrāhīms, die Hidschra Lūṭs, und die Mächtigen, die einer nach dem anderen fielen – Qārūn, Pharao, Hāmān. In der Mitte steht das berühmte Gleichnis: Wer sich andere Beschützer als Allah nimmt, gleicht der Spinne, die sich ein Haus baut – „und das schwächste der Häuser ist das Haus der Spinne“. Die Sure gibt auch Werkzeuge für den Weg: das Gebet, das vom Schändlichen abhält (29:45), das Gespräch mit den Schriftbesitzern „auf die beste Art“ (29:46), die weite Erde für den, der wegen seines Glaubens auswandern muss, und das Schlussversprechen: „Diejenigen, die sich um Unsretwillen abmühen, werden Wir gewiss Unsere Wege leiten.“",
schluessel: {arab: "أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ", ueb: "Meinen die Menschen, dass sie in Ruhe gelassen werden, nur weil sie sagen: „Wir glauben“, ohne dass sie geprüft werden?", ref: "29:2"},
kontext: ["Die Sure fällt in die Jahre, in denen die Verfolgung in Mekka am härtesten war: Boykott, Folter, Spott, der Tod Abū Ṭālibs und Chadīdschas, die Ablehnung in Ṭāʾif. Manche Muslime fragten sich, warum Allah die Gläubigen so leiden lässt. Die Antwort der Sure: Prüfung ist kein Zeichen, dass Allah dich verlassen hat, sondern das normale Gesetz des Glaubens – „Wir haben bereits diejenigen vor ihnen geprüft“ (29:3).",
"Vers 8 hat einen bekannten Anlass: Saʿd ibn Abī Waqqāṣ war seiner Mutter sehr ergeben. Als er Muslim wurde, schwor sie, nicht zu essen und nicht zu trinken, bis er den Islam verlässt. Da kam herab: „Wir haben dem Menschen auferlegt, seine Eltern gut zu behandeln. Wenn sie sich aber abmühen, dich dazu zu bringen, Mir beizugesellen, wovon du kein Wissen hast, so gehorche ihnen nicht“ (Sahih Muslim, Nr. 1748). Die Balance ist bemerkenswert: Güte bleibt Pflicht, Gehorsam im Unglauben nicht.",
"Die Sure bereitet auf die Hidschra vor: „O Meine Diener, die ihr glaubt, Meine Erde ist weit, so dient Mir allein“ (29:56) – und tröstet die Auswanderer wegen des Lebensunterhalts: „Wie viele Tiere tragen ihre Versorgung nicht mit sich – Allah versorgt sie und euch“ (29:60). Kurz danach brach die Gemeinde nach Medina auf."],
asbab: [
 {text: "Vers 8: Die Mutter des Saʿd ibn Abī Waqqāṣ schwor, nicht zu essen und zu trinken, bis er den Islam verlässt – darauf kam der Vers über Güte gegenüber Eltern ohne Gehorsam im Schirk herab.", quelle: "Sahih Muslim, Nr. 1748"},
 {text: "Verse 1–11: Manche Überlieferungen beziehen sie auf Muslime in Mekka, die unter Folter schwach wurden, andere auf die späteren Heuchler in Medina; deshalb halten einige Gelehrte diese Verse für medinensisch.", quelle: "Tafsir aṭ-Ṭabarī und Ibn Kathīr zu 29:1–11"}
],
begriffe: [
 {arab: "يُفْتَنُون", tr: "yuftanūn", wurzel: "f-t-n", erkl: "„Geprüft werden“ – von fitna, ursprünglich das Erhitzen von Gold im Feuer, um es von Unreinheit zu trennen (vgl. Lektion 27). Prüfung reinigt den Glauben wie Feuer das Gold."},
 {arab: "الْعَنْكَبُوت", tr: "al-ʿankabūt", wurzel: "ʿ-n-k-b", erkl: "Die Spinne (29:41) – ihr Netz ist kunstvoll, aber das schwächste Haus: Es schützt weder vor Wind noch vor Regen noch vor Feinden. So ist jede Sicherheit, die man ohne Allah sucht – Geld, Menschen, Macht."},
 {arab: "الْفَحْشَاء وَالْمُنكَر", tr: "al-faḥschāʾ wa-l-munkar", wurzel: "f-ḥ-sch / n-k-r", erkl: "Das Schändliche und das Verwerfliche (29:45): „Das Gebet hält vom Schändlichen und Verwerflichen ab.“ Wenn dein Gebet dich nicht verändert, liegt das nicht am Gebet, sondern an der Art, wie du betest."},
 {arab: "بِالَّتِي هِيَ أَحْسَنُ", tr: "bi-llatī hiya aḥsan", wurzel: "ḥ-s-n", erkl: "„Auf die beste Art“ (29:46) – so sollen Muslime mit Juden und Christen diskutieren, außer mit denen, die Unrecht tun. Der Ton ist Teil der Wahrheit."},
 {arab: "الْحَيَوَان", tr: "al-ḥayawān", wurzel: "ḥ-y-y", erkl: "„Das wahre Leben“ (29:64): „Das diesseitige Leben ist nur Zerstreuung und Spiel, aber die jenseitige Wohnstätte ist wahrlich das (eigentliche) Leben.“ Die Wortform drückt Fülle und Dauer des Lebens aus."},
 {arab: "جَاهَدُوا فِينَا", tr: "dschāhadū fīnā", wurzel: "dsch-h-d", erkl: "„Die sich um Unsretwillen abmühen“ (29:69) – eine mekkanische Stelle, an der Dschihād eindeutig die Anstrengung auf dem Weg zu Allah bedeutet: im Lernen, in der Geduld, im Kampf gegen die eigene Seele. Das Versprechen: „Wir werden sie gewiss Unsere Wege leiten.“"}
],
tafsir: [
 {vers: "Verse 1–13", text: "Das Gesetz der Prüfung: „Allah wird gewiss diejenigen kennen, die wahrhaftig sind, und Er wird gewiss die Lügner kennen“ (29:3). Ibn Kathīr: Allah weiß alles im Voraus, aber die Prüfung macht es sichtbar und begründet Lohn und Strafe. Dann die Menschen, die bei der ersten Bedrängnis die Prüfung der Menschen wie die Strafe Allahs behandeln – und sich sofort als Verbündete zeigen, wenn Erfolg kommt. Vers 8 (Saʿd und seine Mutter) zeigt die Grenze des Gehorsams. Und die Verführer, die sagen: „Folgt unserem Weg, wir tragen eure Sünden“ – sie werden nichts davon tragen, sondern ihre eigenen Lasten und zusätzliche dazu (vgl. 53:38, Lektion 23)."},
 {vers: "Verse 14–27", text: "Nūḥ blieb „tausend Jahre weniger fünfzig“ unter seinem Volk (29:14) – die längste Geduld der Prophetengeschichte. Dann Ibrāhīm: Er argumentiert gegen die Götzen, die keine Versorgung besitzen – „so sucht die Versorgung bei Allah“ (29:17) – und wird ins Feuer geworfen, aus dem Allah ihn rettet. Sein Satz an das Volk: „Ihr habt euch statt Allah Götzen genommen aus Liebe untereinander im diesseitigen Leben“ (29:25). As-Saʿdī: Manche halten am Falschen nicht aus Überzeugung fest, sondern aus Gruppenzugehörigkeit. Lūṭ glaubt ihm, und Ibrāhīm sagt: „Ich wandere zu meinem Herrn aus“ – die erste Hidschra der Geschichte als Vorbild für die bevorstehende Hidschra des Propheten ﷺ."},
 {vers: "Verse 28–44", text: "Lūṭ und sein Volk, Schuʿaib und Madyan, ʿĀd und Ṯamūd, Qārūn, Pharao und Hāmān – „jeden ergriffen Wir wegen seiner Sünde: Auf einige sandten Wir einen Steinsturm, einige ergriff der Schrei, einige ließen Wir in der Erde versinken und einige ertränkten Wir“ (29:40). Dann das Spinnengleichnis 29:41. Al-Qurṭubī: Das Netz sieht von außen wie ein Haus aus; erst der erste Windstoß zeigt seine Schwäche. Ebenso zeigt die Prüfung, ob deine Sicherheiten tragen. „Diese Gleichnisse prägen Wir für die Menschen, doch nur die Wissenden verstehen sie.“"},
 {vers: "Verse 45–55", text: "Die Werkzeuge: „Trag vor, was dir vom Buch offenbart wurde, und verrichte das Gebet. Das Gebet hält vom Schändlichen und Verwerflichen ab, und das Gedenken Allahs ist wahrlich größer“ (29:45). Ibn Kathīr: Das Gebet hat zwei Wirkungen – es hält vom Bösen ab und es ist selbst Gedenken, das Größte überhaupt. Dann 29:46, das Gespräch mit den Schriftbesitzern auf die beste Art: „Sagt: Wir glauben an das, was zu uns herabgesandt wurde und zu euch herabgesandt wurde; unser Gott und euer Gott ist einer.“ Und 29:48: Der Prophet ﷺ konnte vorher kein Buch lesen und schreiben – sonst hätten die Zweifler einen Vorwand gehabt."},
 {vers: "Verse 56–69", text: "Aufruf zur Hidschra und das Versprechen der Versorgung (29:56–60). „Jede Seele wird den Tod kosten, dann werdet ihr zu Uns zurückgebracht“ (29:57). Die Widersprüchlichkeit der Götzendiener: Fragt man sie, wer Himmel und Erde erschaffen hat, sagen sie: Allah; auf dem Meer in Gefahr rufen sie Allah aufrichtig an – doch an Land gesellen sie Ihm wieder bei (29:61–65). Dann der Satz über das wahre Leben (29:64). Und der Schlussvers 29:69: „Diejenigen, die sich um Unsretwillen abmühen, werden Wir gewiss Unsere Wege leiten. Allah ist mit denen, die Gutes tun.“ As-Saʿdī: Die Wege (Plural): Wer sich anstrengt, dem öffnet Allah mehrere Türen zum Guten."}
],
ahadith: [
 {text: "Saʿd ibn Abī Waqqāṣ: Seine Mutter schwor, nicht mit ihm zu sprechen, nicht zu essen und nicht zu trinken, bis er seinen Glauben aufgibt; da sandte Allah 29:8 herab.", quelle: "Sahih Muslim, Nr. 1748"},
 {text: "Chabbāb klagte über die Verfolgung; der Prophet ﷺ erinnerte an Frühere, die zersägt wurden und dennoch nicht von ihrer Religion abließen: „… Doch ihr seid ungeduldig.“", quelle: "Sahih al-Buchari, Nr. 3612"},
 {text: "„Glaubt den Leuten der Schrift nicht und erklärt sie nicht für Lügner, sondern sagt: Wir glauben an Allah und an das, was zu uns herabgesandt wurde …“", quelle: "Sahih al-Buchari, Nr. 4485"},
 {text: "„Die am härtesten geprüften Menschen sind die Propheten, dann die Nächstbesten … Der Mensch wird nach dem Maß seiner Religion geprüft.“", quelle: "Sunan at-Tirmidhī, Nr. 2398; hasan sahih"}
],
hanafi: "Zu 29:8 (Güte gegenüber nichtmuslimischen Eltern): Nach hanafitischer Schule bleibt die Unterhaltspflicht (nafaqa) eines Kindes gegenüber seinen bedürftigen Eltern bestehen, auch wenn die Eltern keine Muslime sind – die Religionsverschiedenheit hebt diese Pflicht zwischen Eltern und Kindern nicht auf (so in al-Hidāya im Kapitel über den Unterhalt). Der Vers trennt also klar: Gehorsam im Unglauben – nein; Versorgung, Respekt und gute Behandlung – ja (vgl. 31:15: „begleite sie im Diesseits auf rechtliche Weise“).",
umsetzung: [
 "Wenn dich eine Prüfung trifft, lies 29:2–3 und sage dir: Das ist kein Zeichen, dass Allah mich verlassen hat, sondern dass Er meinen Glauben sichtbar machen will.",
 "Prüfe dein Spinnennetz: Welche Sicherheit (Job, Konto, Kontakte) hältst du für dein festes Haus? Stärke daneben bewusst deine Verbindung zu Allah durch Duʿā und Tawakkul.",
 "Mach den 29:45-Test: Wenn dein Gebet dich nicht vom Schlechten abhält, verbessere die Qualität – Bedeutung der Fātiḥa lernen, langsamer beten, vor dem Gebet zur Ruhe kommen.",
 "Führe Gespräche mit Christen und Juden nach 29:46: freundlich, mit gemeinsamen Grundlagen beginnen, klar in der Sache.",
 "Mach 29:69 zu deinem Lernvers: Jede Mühe beim Lernen dieser App ist ein dschihād fīnā – und Allah verspricht Wege."
]
},

// ───────────────────────── Lektion 86: Al-Muṭaffifīn ─────────────────────────
{
sure: 83, offb: 86, name: "Al-Muṭaffifīn", arab: "سُورَةُ الْمُطَفِّفِينَ", de: "Die das Maß Kürzenden", verse: 36, ort: "Mekka",
zeit: "Nach der Kairoer Chronologie die letzte mekkanische Sure; nach einem Bericht von Ibn ʿAbbās kam sie herab, als der Prophet ﷺ in Medina ankam",
kurz: "„Wehe den das Maß Kürzenden, die, wenn sie sich von den Menschen zumessen lassen, volles Maß verlangen, wenn sie ihnen aber zumessen oder abwiegen, weniger geben!“ Mit dieser wirtschaftlichen Warnung beginnt die Sure, die genau an der Schwelle zwischen Mekka und Medina steht. Betrug beim Wiegen ist für den Koran kein kleines Vergehen, sondern ein Zeichen dafür, dass man nicht wirklich an den Tag glaubt, „an dem die Menschen vor dem Herrn der Welten stehen“. Dann zeigt die Sure zwei Bücher: Sidschdschīn für die Sittenlosen und ʿIlliyyūn für die Gütigen. Sie erklärt, wie Sünden das Herz überziehen (rān), beschreibt den versiegelten Trank des Paradieses – „darum sollen die Wetteifernden wetteifern“ – und schließt mit einer Umkehrung: Die Spötter, die im Leben über die Gläubigen lachten und einander zuzwinkerten, werden am Ende von den Gläubigen belächelt.",
schluessel: {arab: "كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا يَكْسِبُونَ", ueb: "Keineswegs! Vielmehr hat sich das, was sie erworben haben, über ihre Herzen gelegt.", ref: "83:14"},
kontext: ["Ibn ʿAbbās berichtet: Als der Prophet ﷺ nach Medina kam, gehörten die Leute dort zu den schlimmsten im Maßkürzen. Da sandte Allah herab: „Wehe den das Maß Kürzenden“, und danach maßen sie richtig (Sunan Ibn Mādscha, Nr. 2223; als hasan eingestuft). Andere Gelehrte halten die Sure für mekkanisch. Beides passt zu ihrer Stellung als Brücke: Sie gehört der Verkündigung über Jenseits und Herz an, wie die mekkanischen Suren, und sie richtet sich an den Marktplatz, wie die medinensischen Gesetze.",
"Medina war eine Agrar- und Handelsstadt; Datteln, Getreide und Waren wurden mit Maßen und Gewichten gehandelt. Das kleine Abzwacken beim Abmessen war weit verbreitet und galt als geschickt. Der Koran nennt es beim Namen und verbindet es mit dem Glauben: Wer so handelt, rechnet nicht mit einer Abrechnung. Schon die Geschichte Schuʿaibs und Madyans (7:85, Lektion 39) hatte dieses Thema – jetzt trifft es die neue Gemeinschaft direkt.",
"Wichtig für deine Tazkiya ist Vers 14 über ar-rān: Sünden sind nicht nur einzelne Fehler, sondern hinterlassen Spuren auf dem Herzen. Der Hadith erklärt: Jede Sünde setzt einen schwarzen Punkt; mit Reue wird das Herz poliert, mit weiteren Sünden wächst der Belag, bis er das Herz bedeckt (Sunan at-Tirmidhī, Nr. 3334). Tazkiya ist damit auch eine regelmäßige Reinigung des Herzens."],
asbab: [
 {text: "Ibn ʿAbbās: Als der Prophet ﷺ nach Medina kam, gehörten die Leute zu den schlimmsten im Maßkürzen; da kam „Wehe den das Maß Kürzenden“ herab, und danach maßen sie korrekt.", quelle: "Sunan Ibn Mādscha, Nr. 2223; hasan"}
],
begriffe: [
 {arab: "الْمُطَفِّفِين", tr: "al-muṭaffifīn", wurzel: "ṭ-f-f", erkl: "„Die das Maß Kürzenden“ – ṭafīf ist das Geringe, das kleine Fehlende. Gemeint sind Menschen, die beim Geben ein wenig abzwacken und beim Nehmen genau nachmessen. Übertragen gilt das auch für Arbeitszeit, Löhne, Rechte und Lob."},
 {arab: "سِجِّين", tr: "sidschdschīn", wurzel: "s-dsch-n", erkl: "Das Register der Sittenlosen (83:7), verwandt mit sidschn (Gefängnis): ein Ort der Enge und Tiefe, an dem ihre Taten verzeichnet sind."},
 {arab: "عِلِّيُّون", tr: "ʿilliyyūn", wurzel: "ʿ-l-w", erkl: "Das Register der Gütigen (83:18) – von ʿuluww (Höhe): ein erhabener Ort, „den die Nahegestellten bezeugen“. Die Taten der Guten steigen auf, die der Bösen sinken."},
 {arab: "رَانَ", tr: "rāna", wurzel: "r-y-n", erkl: "„Hat sich (wie Rost) darüber gelegt“ – rān ist ein Belag, der das Herz verdunkelt, bis es die Wahrheit nicht mehr erkennt. Die Ursache: „was sie erworben haben“, also die eigenen Taten."},
 {arab: "فَلْيَتَنَافَسِ الْمُتَنَافِسُون", tr: "fa-l-yatanāfasi l-mutanāfisūn", wurzel: "n-f-s", erkl: "„Darum sollen die Wetteifernden wetteifern“ (83:26) – von nafīs, das Kostbare. Der Koran verbietet nicht den Wettbewerb, sondern lenkt ihn: Wetteifere um das Kostbarste, nicht um das Vergängliche (vgl. takāthur, Lektion 16)."},
 {arab: "يَتَغَامَزُون", tr: "yataġāmazūn", wurzel: "ġ-m-z", erkl: "„Sie zwinkerten einander zu“ (83:30) – das spöttische Zeichen hinter dem Rücken der Gläubigen. Vgl. humaza und lumaza in Lektion 32."}
],
tafsir: [
 {vers: "Verse 1–6", text: "„Wehe den das Maß Kürzenden …“ Dann die entscheidende Frage: „Glauben diese denn nicht, dass sie auferweckt werden zu einem gewaltigen Tag, dem Tag, an dem die Menschen vor dem Herrn der Welten stehen?“ Ibn Kathīr: Der Betrug im Kleinen verrät den Unglauben im Großen. Der Hadith Ibn ʿUmars beschreibt dieses Stehen: Die Menschen stehen im Schweiß bis zur Mitte ihrer Ohren (Sahih al-Buchari, Nr. 4938; Sahih Muslim, Nr. 2862). Für ein paar Gramm Vorteil riskiert der Betrüger diesen Tag."},
 {vers: "Verse 7–17", text: "„Das Buch der Sittenlosen ist in Sidschdschīn … ein geschriebenes Buch.“ Wehe den Leugnern, die den Tag des Gerichts für Lüge erklären – „nur jeder maßlose Sünder erklärt ihn für Lüge; wenn ihm Unsere Verse vorgetragen werden, sagt er: Fabeln der Früheren“. Dann 83:14: „Keineswegs! Vielmehr hat sich über ihre Herzen gelegt, was sie erworben haben.“ Al-Qurṭubī: Nicht der Koran ist unverständlich, sondern das Herz ist zugedeckt. „Keineswegs! Sie werden an jenem Tag von ihrem Herrn ausgeschlossen sein“ (83:15). Viele Gelehrte schlossen daraus: Wenn die Ungläubigen ausgeschlossen werden, sehen die Gläubigen ihren Herrn (vgl. 75:23, Lektion 31)."},
 {vers: "Verse 18–28", text: "„Das Buch der Gütigen ist in ʿIlliyyūn … die Nahegestellten bezeugen es.“ Die Gütigen sind in Wonne, auf Liegen schauend; „du erkennst auf ihren Gesichtern das Strahlen der Wonne“. Sie trinken versiegelten, reinen Wein, „dessen Siegel Moschus ist – und darum sollen die Wetteifernden wetteifern“, gemischt aus Tasnīm, einer Quelle, aus der die Nahegestellten trinken. As-Saʿdī: Der Wein des Paradieses hat nichts von den Schäden des irdischen – kein Rausch, kein Kopfweh, kein Streit. Wer im Diesseits verzichtet, um Allahs Willen, bekommt das Reine im Jenseits."},
 {vers: "Verse 29–36", text: "„Diejenigen, die Verbrechen begingen, pflegten über die Gläubigen zu lachen; wenn sie an ihnen vorbeigingen, zwinkerten sie einander zu; wenn sie zu ihren Angehörigen zurückkehrten, kehrten sie vergnügt zurück; und wenn sie sie sahen, sagten sie: Diese sind wahrlich Irregehende.“ Doch sie waren nicht als Aufseher über sie gesandt. „Heute aber lachen die Gläubigen über die Ungläubigen.“ Ibn Kathīr: Die Rollen kehren sich um. Die Frage am Ende ist bitter-ironisch: „Ist den Ungläubigen etwa vergolten worden, was sie zu tun pflegten?“ Für die verfolgten Muslime, die gerade nach Medina gezogen waren, ein großer Trost."}
],
ahadith: [
 {text: "Ibn ʿAbbās: Als der Prophet ﷺ nach Medina kam, waren die Leute die schlimmsten im Maßkürzen; nach der Herabsendung dieser Sure maßen sie richtig.", quelle: "Sunan Ibn Mādscha, Nr. 2223; hasan"},
 {text: "„Wenn der Diener eine Sünde begeht, wird in seinem Herzen ein schwarzer Punkt gesetzt. Lässt er davon ab, bittet um Vergebung und bereut, wird sein Herz poliert. Kehrt er zurück, wird der Punkt vergrößert, bis er sein Herz überzieht – das ist der rān, den Allah erwähnt.“", quelle: "Sunan at-Tirmidhī, Nr. 3334; hasan sahih"},
 {text: "Zu 83:6: „Am Tag, an dem die Menschen vor dem Herrn der Welten stehen“ – einer von ihnen steht in seinem Schweiß bis zur Mitte seiner Ohren.", quelle: "Sahih al-Buchari, Nr. 4938; Sahih Muslim, Nr. 2862"},
 {text: "„Wer uns betrügt, gehört nicht zu uns.“ – gesprochen auf dem Markt, als der Prophet ﷺ nasses Getreide unter trockenem fand.", quelle: "Sahih Muslim, Nr. 102"}
],
hanafi: "Das Verbot des Maßkürzens ist im hanafitischen Kaufrecht konkret ausgearbeitet. Einige Regeln: Wer eine Ware mit verdecktem Mangel verkauft, ohne ihn offenzulegen, sündigt, und der Käufer hat das Recht, die Ware zurückzugeben (chiyār al-ʿaib). Wer beim Kauf nach Gewicht oder Maß weniger erhält als vereinbart, hat Anspruch auf den Fehlbetrag. Täuschende Werbung oder das Verdecken schlechter Ware unter guter (vgl. Muslim 102) gilt als Betrug (ġischsch). Übertragen auf die heutige Arbeitswelt sagen die Gelehrten: Auch der Angestellte, der bezahlte Zeit verschwendet, und der Arbeitgeber, der Lohn zurückhält, fallen unter den Geist von „Wehe den Maßkürzenden“.",
umsetzung: [
 "Mache einen Taṭfīf-Check in deinem Leben: Gibst du bei Arbeitszeit, Lohn, Rechnungen, Versprechen und Lob das volle Maß? Korrigiere eine Stelle sofort.",
 "Poliere dein Herz gegen ar-rān: Mach täglich bewusst Istiġfār (mindestens 70- bis 100-mal, wie der Prophet ﷺ) und zeitnahe Tauba nach jeder Sünde (Tirmidhī 3334).",
 "Lenke deinen Ehrgeiz nach 83:26: Wetteifere mit Freunden um gute Taten – wer liest mehr Koran, wer spendet regelmäßiger – statt um Statussymbole.",
 "Wenn du wegen deines Glaubens belächelt wirst: Lies 83:29–36 und bleib gelassen. Das letzte Lachen gehört nicht den Spöttern."
]
},

// ───────────────────────── Lektion 87: Al-Baqara ─────────────────────────
{
sure: 2, offb: 87, name: "Al-Baqara", arab: "سُورَةُ الْبَقَرَةِ", de: "Die Kuh", verse: 286, ort: "Medina",
zeit: "Medinensisch – begonnen im ersten und zweiten Jahr nach der Hidschra (ab 622 n. Chr.) und über Jahre ergänzt; ihre Zinsverse gehören zu den letzten Offenbarungen überhaupt",
kurz: "Mit Al-Baqara beginnt die medinensische Phase – und das längste Kapitel des Korans. Nach 13 Jahren in Mekka, in denen das Herz geformt wurde, hat die Gemeinde jetzt eine Stadt, Nachbarn, Verträge, Märkte und Feinde. Darum bringt diese Sure das Grundgesetz der neuen Gemeinschaft: Sie beginnt mit drei Menschentypen (Gottesfürchtige, Ungläubige, Heuchler), erzählt die Erschaffung Ādams, die lange Geschichte der Kinder Israels mit ihren Lehren, den Bau der Kaaba durch Ibrāhīm und Ismāʿīl und den Wechsel der Gebetsrichtung nach Mekka. Dann folgen Fasten, Pilgerfahrt, Kampfregeln, Ehe- und Scheidungsrecht, Spenden, das Zinsverbot und der längste Vers des Korans über Schulden. Mittendrin steht der größte Vers des Korans, Āyat al-Kursī. Und sie endet mit einem Gebet, das Allah selbst beantwortet hat: „Unser Herr, lade uns nicht auf, wofür wir keine Kraft haben.“",
schluessel: {arab: "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ", ueb: "Allah – es gibt keinen Gott außer Ihm, dem Lebendigen, dem Beständigen. Ihn überkommt weder Schlummer noch Schlaf.", ref: "2:255 (Āyat al-Kursī)"},
kontext: ["Der Übergang: Im Jahr 622 n. Chr. wanderte der Prophet ﷺ mit seinen Gefährten von Mekka nach Yathrib aus, das fortan Madīnat an-Nabī (die Stadt des Propheten) hieß. Damit änderte sich alles. In Mekka war der Islam eine verfolgte Minderheit ohne eigene Ordnung; in Medina entstand eine Gemeinschaft mit Verantwortung: die Auswanderer (Muhādschirūn), die Helfer aus den Stämmen Aus und Chazradsch (Anṣār), drei große jüdische Stämme mit Verträgen und eine neue Gruppe, die es in Mekka nicht gab – die Heuchler (Munāfiqūn), die sich äußerlich anschlossen, innerlich aber nicht. Deshalb beginnt Al-Baqara mit genau diesen Menschentypen.",
"Der Stil ändert sich: Die Verse werden länger, die Anrede lautet oft „O ihr, die ihr glaubt“ statt „O ihr Menschen“, und es kommen Gesetze. Aber die Gesetze stehen nicht allein: Jede Rechtsregel ist mit Taqwā, Jenseits und Allahs Namen verbunden. Achte darauf, wie oft ein Vers über Scheidung mit „Fürchtet Allah“ oder „Allah ist Allwissend“ endet. Das Recht bleibt eingebettet in die Herzensbildung der Mekka-Zeit.",
"Der Name kommt von der Geschichte der Kuh (2:67–73): Die Kinder Israels sollten eine Kuh schlachten, um einen Mord aufzuklären, stellten aber Frage um Frage und machten sich die Sache dadurch immer schwerer. Die Lehre ist bis heute aktuell: Wer bei klaren Geboten nach Ausflüchten sucht, erschwert sich selbst die Religion. Die Sure wurde nicht in einem Stück offenbart; ihre Teile kamen über viele Jahre herab, die Zinsverse (2:275–281) gehören nach Ibn ʿAbbās zu den allerletzten Offenbarungen (Sahih al-Buchari, Nr. 4544)."],
asbab: [
 {text: "2:144 (Wechsel der Qibla): Der Prophet ﷺ betete etwa 16 oder 17 Monate in Richtung Jerusalem und wünschte sich die Kaaba als Gebetsrichtung; dann kam der Vers herab.", quelle: "Sahih al-Buchari, Nr. 399 und 40 (al-Barāʾ ibn ʿĀzib)"},
 {text: "2:158 (Ṣafā und Marwa): Die Anṣār hatten Bedenken, zwischen den beiden Hügeln zu laufen, weil dort früher Götzen standen; ʿĀʾischa erklärt den Anlass.", quelle: "Sahih al-Buchari, Nr. 1643; Sahih Muslim, Nr. 1277"},
 {text: "2:187 (Erleichterung in den Fastennächten): Qais ibn Ṣirma fiel nach der Arbeit vor dem Essen in Schlaf und durfte nach der früheren Regel nichts mehr essen; dazu und zum Faden des ʿAdī ibn Ḥātim kamen die Erklärungen.", quelle: "Sahih al-Buchari, Nr. 1915 und 1916"},
 {text: "2:222 (Menstruation): Anders als manche damals, die sich von menstruierenden Frauen völlig absonderten, erlaubte der Islam alles außer dem Geschlechtsverkehr.", quelle: "Sahih Muslim, Nr. 302"},
 {text: "2:256 (Kein Zwang in der Religion): Die Kinder der Anṣār, die jüdisch erzogen worden waren, sollten nicht zum Islam gezwungen werden (siehe Brennpunkt-Verse).", quelle: "Sunan Abū Dāwūd, Nr. 2682; sahih"},
 {text: "2:284–286: Die Gefährten erschraken über „ob ihr offenlegt, was in euch ist, oder es verbergt, Allah rechnet es euch an“ – nach ihrem „Wir hören und gehorchen“ kam die Erleichterung der Schlussverse.", quelle: "Sahih Muslim, Nr. 125 und 126"}
],
begriffe: [
 {arab: "الْمُتَّقِين / الْغَيْب", tr: "al-muttaqīn / al-ġaib", wurzel: "w-q-y / ġ-y-b", erkl: "Die Gottesfürchtigen, die „an das Verborgene glauben“ (2:2–3): Der Koran ist Rechtleitung für sie. Der erste Schritt des Glaubens ist, an das zu glauben, was man nicht sieht (vgl. Lektion 40)."},
 {arab: "النِّفَاق", tr: "an-nifāq", wurzel: "n-f-q", erkl: "Heuchelei – von nafaq, ein Tunnel mit zwei Ausgängen, wie der Bau einer Wüstenmaus, die immer einen Fluchtweg hat. Der Heuchler hat einen Ausgang zu den Gläubigen und einen zu den Ungläubigen (2:8–20)."},
 {arab: "الْقِبْلَة", tr: "al-qibla", wurzel: "q-b-l", erkl: "Die Gebetsrichtung – zuerst Jerusalem, dann die Kaaba (2:142–150). Der Wechsel war eine Prüfung, „damit Wir wissen, wer dem Gesandten folgt und wer sich auf den Fersen umkehrt“ (2:143)."},
 {arab: "أُمَّةً وَسَطًا", tr: "ummatan wasaṭā", wurzel: "w-s-ṭ", erkl: "„Eine Gemeinschaft der Mitte“ (2:143) – ausgewogen, gerecht, die Beste. Mitte heißt nicht Lauheit, sondern Gleichgewicht zwischen Übertreibung und Vernachlässigung, damit die Umma „Zeugen über die Menschen“ sein kann."},
 {arab: "الصِّيَام", tr: "aṣ-ṣiyām", wurzel: "ṣ-w-m", erkl: "Das Fasten (2:183–187) – wörtlich „sich enthalten“. Sein Ziel steht im Vers: „… damit ihr gottesfürchtig werdet“ (laʿallakum tattaqūn). Fasten ist Taqwā-Training."},
 {arab: "الْكُرْسِيّ", tr: "al-kursiyy", wurzel: "k-r-s", erkl: "„Der Fußschemel/Thronsitz“ Allahs, der „die Himmel und die Erde umfasst“ (2:255). Ibn ʿAbbās: der Ort der Füße. Ahl as-Sunna bestätigen ihn, ohne das Wie zu beschreiben; der Vers zeigt die unvorstellbare Größe Allahs."},
 {arab: "الرِّبَا", tr: "ar-ribā", wurzel: "r-b-w", erkl: "Zins/Wucher – vermehrter Rückzahlungsbetrag bei Darlehen und bestimmte ungleiche Tauschgeschäfte. Endgültig verboten in 2:275–281: „Allah hat den Handel erlaubt und den Zins verboten.“ Wer ihn fortsetzt, erhält eine „Kriegsansage von Allah und Seinem Gesandten“."},
 {arab: "الدَّيْن", tr: "ad-dain", wurzel: "d-y-n", erkl: "Die Schuld (2:282) – der längste Vers des Korans regelt, wie Schulden aufgeschrieben und bezeugt werden. Gleiche Wurzel wie dīn (Religion, Gericht): Wer Schulden ernst nimmt, nimmt die Abrechnung ernst."}
],
tafsir: [
 {vers: "Verse 1–20: drei Menschentypen", text: "„Dies ist das Buch, an dem kein Zweifel ist, eine Rechtleitung für die Gottesfürchtigen.“ Dann ihre Merkmale: Glaube an das Verborgene, Gebet, Spenden, Glaube an das Herabgesandte und Gewissheit über das Jenseits. Zwei Verse über die Ungläubigen, deren Herzen versiegelt sind. Und dreizehn Verse über die Heuchler – sie sagen „Wir glauben“ und sind es nicht, sie meinen, Allah zu betrügen, und betrügen nur sich selbst; „in ihren Herzen ist Krankheit“. Zwei Gleichnisse: der Mann, der ein Feuer anzündet und dessen Licht Allah wegnimmt, und Menschen im Gewitter, die ihre Finger in die Ohren stecken. Ibn Kathīr: Dass Allah den Heuchlern so viel Raum gibt, zeigt, wie gefährlich sie für eine Gemeinschaft sind – und dass jeder Gläubige sich selbst auf Spuren von nifāq prüfen soll."},
 {vers: "Verse 21–39: Ādam und der Auftrag des Menschen", text: "Der erste Aufruf an alle Menschen: „O ihr Menschen, dient eurem Herrn, Der euch und die vor euch erschaffen hat.“ Dann die Herausforderung: Bringt eine Sure gleicher Art hervor (2:23). Dann die Erschaffung Ādams: „Ich werde auf der Erde einen Nachfolger (chalīfa) einsetzen.“ Die Engel fragen, ob er Verderben stiften wird; Allah lehrt Ādam die Namen aller Dinge – Wissen ist der Grund seiner Würde. Iblīs verweigert die Niederwerfung (vgl. Lektion 38 und 39). Ādam und seine Frau werden durch den Satan zum Fehltritt verleitet, dann „empfing Ādam Worte von seinem Herrn, und Er wandte sich ihm zu“ (2:37). As-Saʿdī: Der Mensch ist zum Verwalter der Erde bestimmt, ausgestattet mit Wissen, anfällig für Fehler und eingeladen zur Reue."},
 {vers: "Verse 40–123: die Kinder Israels", text: "Der längste Block der Sure ist an die Kinder Israels gerichtet: Allah erinnert an Seine Gaben (Rettung vor Pharao, Manna und Wachteln, das Wasser aus dem Felsen) und an ihre wiederholten Brüche des Bundes (das Kalb, die Forderung, Allah offen zu sehen, die Verdrehung der Worte, die Geschichte der Kuh, das Töten von Propheten, Hārūt und Mārūt in Babel). Ibn Kathīr und as-Saʿdī betonen: Das ist keine Polemik gegen ein Volk, sondern ein Spiegel für die neue Umma – dieselben Fehler drohen jeder Gemeinschaft mit einer Offenbarung: Wissen ohne Handeln, Ausflüchte bei klaren Geboten, Stolz auf Abstammung. Zugleich steht hier 2:62: Wer von den Juden, Christen und Sabäern an Allah und den Jüngsten Tag glaubt und Gutes tut, dessen Lohn ist bei seinem Herrn – nach der Deutung der Mufassirūn bezogen auf die Gläubigen jeder Offenbarung zu ihrer Zeit."},
 {vers: "Verse 124–152: Ibrāhīm, die Kaaba und die neue Qibla", text: "Ibrāhīm wird von seinem Herrn mit Geboten geprüft und erfüllt sie; er wird zum Vorbild (imām) für die Menschen. Mit Ismāʿīl baut er die Grundmauern des Hauses und betet: „Unser Herr, nimm es von uns an … und erwecke unter ihnen einen Gesandten aus ihrer Mitte, der ihnen Deine Verse verliest, sie das Buch und die Weisheit lehrt und sie läutert (yuzakkīhim)“ (2:127–129) – die Sendung des Propheten ﷺ als Erfüllung dieses Gebets, und Tazkiya als Teil seines Auftrags. Dann der Wechsel der Gebetsrichtung: „Wende dein Gesicht in Richtung der Heiligen Gebetsstätte“ (2:144), mit der Klarstellung, dass Allah den Osten und den Westen besitzt (2:142) und dass die Gebete in Richtung Jerusalem nicht verloren sind (2:143). „So gedenkt Meiner, dann gedenke Ich euer; seid Mir dankbar und seid nicht undankbar“ (2:152)."},
 {vers: "Verse 153–177: Geduld, Ṣafā und Marwa, wahre Frömmigkeit", text: "„O ihr, die ihr glaubt, sucht Hilfe in der Geduld und im Gebet“ (2:153). Die Märtyrer sind lebendig (2:154). Dann die Ankündigung der Prüfungen: „Wir werden euch gewiss prüfen mit etwas Furcht, Hunger, Minderung an Besitz, Leben und Früchten – verkünde den Geduldigen frohe Botschaft, die, wenn sie ein Unglück trifft, sagen: Wir gehören Allah, und zu Ihm kehren wir zurück“ (2:155–156). Ṣafā und Marwa gehören zu den Kultzeichen Allahs (2:158). Die Erinnerung an Allahs Zeichen in der Schöpfung (2:164) und an erlaubte Speisen (2:168–173). Höhepunkt ist 2:177, der Vers der Frömmigkeit (birr): Frömmigkeit ist nicht, das Gesicht nach Osten oder Westen zu wenden, sondern Glaube, Spenden aus Liebe zu Allah an Verwandte, Waisen, Arme, Reisende, Bittende und für die Befreiung von Sklaven, Gebet, Zakat, Vertragstreue und Geduld in Not und Krieg."},
 {vers: "Verse 178–203: Qiṣāṣ, Testament, Fasten, Kampf, Pilgerfahrt", text: "Das Recht der Vergeltung bei Tötung (2:178–179), mit der Möglichkeit der Vergebung und des Blutgeldes – „in der Wiedervergeltung liegt Leben für euch“: Gerechtigkeit verhindert Blutrache. Das Testament (2:180–182). Das Fasten (2:183–187): vorgeschrieben „wie denen vor euch“, für Kranke und Reisende mit Nachholen, Ramadan als Monat des Korans, die Nähe Allahs mitten im Fastenblock: „Wenn Meine Diener dich nach Mir fragen – Ich bin nahe; Ich erhöre das Gebet des Bittenden“ (2:186). Dann der erste große Kampfabschnitt 2:190–195: Kampf gegen die, die gegen euch kämpfen, ohne Maßüberschreitung – ausführlich erklärt in den Brennpunkt-Versen; dazu 2:195: „Gebt auf dem Weg Allahs aus und stürzt euch nicht mit eigener Hand ins Verderben; tut Gutes.“ Schließlich die Pilgerfahrt (2:196–203) mit ihren Regeln und dem Gebet „Unser Herr, gib uns im Diesseits Gutes und im Jenseits Gutes und bewahre uns vor der Strafe des Feuers“ (2:201)."},
 {vers: "Verse 204–242: Gemeinschaftsfragen und Familienrecht", text: "Der Mensch mit schönen Worten und verderblichen Taten (2:204–206) und der, der sich für Allahs Wohlgefallen hingibt (2:207). „Tretet allesamt in den Frieden (as-silm) ein und folgt nicht den Fußstapfen des Satans“ (2:208). Fragen der Gefährten: Spenden, Kampf im heiligen Monat, Wein und Glücksspiel – „in beiden liegt große Sünde und Nutzen für die Menschen, doch ihre Sünde ist größer als ihr Nutzen“ (2:219), eine Zwischenstufe vor dem endgültigen Verbot in 5:90. Waisen, Ehe mit Götzendienern (2:221), Menstruation (2:222). Dann das Scheidungsrecht: Wartezeit von drei Perioden (2:228), „die Scheidung ist zweimal; dann entweder Behalten in rechtlicher Weise oder Entlassen in guter Weise“ (2:229), Loskauf der Frau (chulʿ), Stillzeit von zwei vollen Jahren (2:233), Wartezeit der Witwe (2:234). Immer wieder: „Vergesst nicht die Großzügigkeit untereinander“ (2:237). Und mitten in den Scheidungsversen der Befehl: „Haltet die Gebete ein, besonders das mittlere Gebet“ (2:238) – Recht und Gottesdienst gehören zusammen."},
 {vers: "Verse 243–260: Ṭālūt, Āyat al-Kursī, kein Zwang, Ibrāhīm", text: "Die Geschichte Ṭālūts und Dschālūts (Saul und Goliath): Ein kleines Heer, geprüft am Fluss, besiegt mit Allahs Erlaubnis ein großes – „wie manche kleine Schar hat schon eine große besiegt“ (2:249); Dāwūd tötet Dschālūt. Dann Āyat al-Kursī (2:255), der größte Vers des Korans: zehn Sätze über Allah – Lebendig, Beständig, ohne Schlaf, Eigentümer von allem, Fürsprache nur mit Seiner Erlaubnis, allwissend, Sein Kursī umfasst Himmel und Erde, ihre Bewahrung ermüdet Ihn nicht, Er ist der Erhabene, der Gewaltige. Direkt danach 2:256: „Es gibt keinen Zwang in der Religion“ (siehe Brennpunkte). Dann Ibrāhīms Streit mit dem König, der sich anmaßte, Leben zu geben und Tod (2:258), der Mann, der hundert Jahre tot war (2:259), und Ibrāhīms Bitte, zu sehen, wie Allah die Toten lebendig macht, „damit mein Herz Ruhe findet“ (2:260)."},
 {vers: "Verse 261–283: Spenden, Zins und Schulden", text: "Das Gleichnis der Spende: wie ein Korn, das sieben Ähren wachsen lässt, in jeder Ähre hundert Körner (2:261). Spenden ohne Vorhalten und Kränken (2:262–264), aus dem Guten, nicht aus dem Schlechten (2:267), offen oder – besser – im Verborgenen an Bedürftige (2:271), besonders an die, die man wegen ihrer Zurückhaltung für reich hält (2:273). Dann das Zinsverbot (2:275–281): Wer Zins nimmt, steht auf wie einer, den der Satan durch Berührung verwirrt hat; „Allah tilgt den Zins und lässt die Almosen wachsen“; wer nicht ablässt, dem gilt „Krieg von Allah und Seinem Gesandten“; dem zahlungsunfähigen Schuldner ist Aufschub zu gewähren, und es zu erlassen ist besser. Vers 2:281, nach einer Überlieferung von Ibn ʿAbbās einer der letzten offenbarten Verse: „Hütet euch vor einem Tag, an dem ihr zu Allah zurückgebracht werdet.“ Dann der Schuldenvers 2:282, der längste Vers des Korans – aufschreiben, bezeugen, gerecht verfahren (zur Zeugenregel siehe die Brennpunkt-Verse), und das Pfand bei Reisen (2:283)."},
 {vers: "Verse 284–286: die Schlussverse", text: "„Allah gehört, was in den Himmeln und auf der Erde ist. Ob ihr offenlegt, was in euch ist, oder es verbergt – Allah rechnet es euch an.“ Die Gefährten erschraken: Wer kann seine Gedanken beherrschen? Der Prophet ﷺ lehrte sie zu sagen: „Wir hören und gehorchen.“ Darauf kamen die zwei Schlussverse: „Der Gesandte glaubt an das, was zu ihm von seinem Herrn herabgesandt wurde, und die Gläubigen … Allah erlegt keiner Seele mehr auf, als sie zu leisten vermag.“ Und das Gebet: „Unser Herr, belange uns nicht, wenn wir vergessen oder Fehler begehen … lade uns nicht auf, wofür wir keine Kraft haben, verzeih uns, vergib uns und erbarme Dich unser.“ Nach dem Hadith antwortete Allah auf jede Bitte: „Ich habe es getan“ (Sahih Muslim, Nr. 126). Die Sure, die mit drei Menschentypen begann, endet mit der Gemeinschaft, die hört, gehorcht und um Vergebung bittet."}
],
ahadith: [
 {text: "Der Prophet ﷺ fragte Ubayy ibn Kaʿb: „Welcher Vers im Buch Allahs ist der gewaltigste?“ – „Allāhu lā ilāha illā huwa l-ḥayyu l-qayyūm.“ – Er schlug ihm auf die Brust und sagte: „Möge dir das Wissen wohl bekommen, Abū l-Mundhir!“", quelle: "Sahih Muslim, Nr. 810"},
 {text: "„Wer die beiden letzten Verse der Sure Al-Baqara in einer Nacht rezitiert, dem genügen sie.“", quelle: "Sahih al-Buchari, Nr. 5009; Sahih Muslim, Nr. 808"},
 {text: "„Macht eure Häuser nicht zu Friedhöfen. Der Satan flieht aus dem Haus, in dem Sure Al-Baqara rezitiert wird.“", quelle: "Sahih Muslim, Nr. 780"},
 {text: "„Lest Al-Baqara, denn sie zu nehmen ist Segen, sie zu lassen ist Verlust, und die Zauberer können ihr nicht beikommen.“", quelle: "Sahih Muslim, Nr. 804"},
 {text: "„Allah verfluchte den, der Zins nimmt, den, der ihn gibt, den, der ihn aufschreibt, und die beiden Zeugen – sie sind gleich.“", quelle: "Sahih Muslim, Nr. 1598"},
 {text: "Ibn ʿAbbās: „Der letzte Vers, der auf den Propheten ﷺ herabgesandt wurde, war der Vers des Zinses.“", quelle: "Sahih al-Buchari, Nr. 4544"}
],
hanafi: "Al-Baqara enthält die meisten Rechtsverse des Korans; hier die wichtigsten hanafitischen Punkte: (1) Fasten: Für das Ramadan-Fasten genügt nach der Schule die Absicht (niyya) noch am Tag bis vor der „großen Mittagszeit“ (aḍ-ḍaḥwa al-kubrā), sofern man seit Fadschr nichts zu sich genommen hat; für Nachholfasten muss sie in der Nacht gefasst werden. (2) Wer im Ramadan absichtlich und ohne Grund isst oder trinkt, muss nach hanafitischer Schule – wie beim Beischlaf – nachholen und die große Sühne (kaffāra: 60 Tage am Stück fasten) leisten; nach den Schāfiʿiten gilt die kaffāra nur beim Beischlaf. (3) Reisende dürfen das Fasten brechen; wenn es ohne Schaden möglich ist, ist Fasten nach 2:184 („Fasten ist besser für euch“) vorzuziehen. (4) Die Wartezeit der geschiedenen Frau beträgt drei qurūʾ – nach den Hanafiten drei Menstruationen (nach den Schāfiʿiten drei Reinheitsphasen). (5) Dreifache Scheidung in einem Satz oder einer Sitzung ist nach hanafitischer Schule eine verbotene Neuerung (ṭalāq bidʿī), aber dennoch als drei wirksam – so auch die Mehrheit der Schulen; die Sunna-Form ist eine einzige Scheidung in einer Reinheitsphase ohne Beischlaf. (6) Zins: Jede vereinbarte Mehrforderung auf ein Darlehen ist Ribā; im Tausch von Gütern, die nach Maß oder Gewicht gehandelt werden und derselben Gattung angehören, ist nach hanafitischer Begründung (ʿilla: Maß/Gewicht plus Gattung) nur gleiche Menge Hand in Hand erlaubt. (7) Das Testament ist auf ein Drittel begrenzt und darf gesetzlichen Erben nicht ohne Zustimmung der übrigen Erben zugutekommen.",
umsetzung: [
 "Lies Āyat al-Kursī nach jedem Pflichtgebet und vor dem Schlafen – zum Schlaf ist der Schutz durch sie in Sahih al-Buchari (Nr. 2311) überliefert, zum Gebet in an-Nasāʾī (as-Sunan al-kubrā; von al-Albānī als sahih eingestuft).",
 "Lies jeden Abend die letzten beiden Verse (2:285–286) – „sie genügen dir“ (Buchari 5009) – und sprich das Gebet am Ende mit Bedeutung.",
 "Rezitiere oder höre Al-Baqara regelmäßig zu Hause, verteilt über eine Woche oder einen Monat (Muslim 780) – ein Haus mit Koran ist geschützt.",
 "Prüfe deine Finanzen auf Ribā: Kredite, Kreditkarten mit Zinsen, Zinskonten. Suche Schritt für Schritt Alternativen und frag bei Unklarheiten einen hanafitischen Gelehrten.",
 "Schreibe Schulden auf (2:282), auch unter Freunden und Verwandten – das ist kein Misstrauen, sondern ein Gebot, das Streit verhindert.",
 "Mach 2:152 zu deinem Tagesvers: „So gedenkt Meiner, dann gedenke Ich euer.“ Jedes Dhikr ist eine Einladung, dass Allah deiner gedenkt."
]
},

// ───────────────────────── Lektion 88: Al-Anfāl ─────────────────────────
{
sure: 8, offb: 88, name: "Al-Anfāl", arab: "سُورَةُ الْأَنْفَالِ", de: "Die Beute", verse: 75, ort: "Medina",
zeit: "Medinensisch – nach der Schlacht von Badr am 17. Ramadan des Jahres 2 n. H. (624 n. Chr.)",
kurz: "Die Sure ist die Nachbesprechung von Badr, der ersten großen Schlacht zwischen den Muslimen und den Quraisch. Etwa 313 schlecht ausgerüstete Muslime standen einem Heer von rund tausend Mann gegenüber, das ausgezogen war, um sie zu vernichten. Die Muslime siegten – und stritten danach über die Beute. Die Sure beginnt deshalb mit einer Korrektur: Die Beute gehört Allah und Seinem Gesandten; „fürchtet Allah und bringt die Beziehungen zwischen euch in Ordnung“. Dann zeigt sie, wer Badr wirklich gewonnen hat: Engel, Regen, Schlaf als Beruhigung, ein Wurf Sand – „nicht du hast geworfen, als du warfst, sondern Allah hat geworfen“. Sie lehrt Standhaftigkeit, Einigkeit und Gehorsam, regelt den Umgang mit Beute, Gefangenen und Verträgen und betont: „Und wenn sie sich dem Frieden zuneigen, so neige auch du dich ihm zu.“",
schluessel: {arab: "إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا", ueb: "Die Gläubigen sind nur diejenigen, deren Herzen sich ängstigen, wenn Allah erwähnt wird, und die, wenn ihnen Seine Verse verlesen werden, an Glauben zunehmen.", ref: "8:2"},
kontext: ["Vorgeschichte: Die Quraisch hatten die Muslime enteignet und vertrieben. Als eine große mekkanische Handelskarawane unter Abū Sufyān auf dem Rückweg von Syrien an Medina vorbeizog, zog der Prophet ﷺ mit etwa 313 Mann aus. Die Karawane entkam, aber Mekka schickte ein Heer von rund tausend Kämpfern. Die Muslime standen vor der Wahl, die die Sure beschreibt: „Ihr wünschtet, dass euch die (Gruppe) ohne Waffen zufiele, Allah aber wollte die Wahrheit durch Seine Worte bestätigen“ (8:7).",
"In der Nacht vor der Schlacht betete der Prophet ﷺ lange: „O Allah, erfülle mir, was Du mir versprochen hast. O Allah, wenn diese kleine Schar vernichtet wird, wirst Du auf der Erde nicht mehr angebetet“ (Sahih Muslim, Nr. 1763). Darauf antwortet 8:9: „Ich werde euch mit tausend Engeln unterstützen.“ Die Muslime siegten; siebzig Mekkaner fielen, darunter Abū Dschahl, siebzig wurden gefangen. Der Tag heißt im Koran yaum al-furqān, der Tag der Unterscheidung (8:41; vgl. Lektion 42).",
"Wichtig für das Verständnis der Kampfverse dieser Sure (z. B. 8:12, siehe Brennpunkt-Verse): Sie beschreiben eine konkrete Schlacht in einem Verteidigungskrieg der Gründergeneration und sind in Kriegsrecht eingebettet, das von der Staatsführung ausgeübt wird. Dieselbe Sure verlangt Vertragstreue, öffentliche Kündigung von Verträgen (8:58) und die Bereitschaft zum Frieden (8:61)."],
asbab: [
 {text: "Das Bittgebet des Propheten ﷺ in der Nacht von Badr und die Antwort mit den Engeln (8:9); dazu die Beratung über die Gefangenen und die Herabsendung von 8:67–69.", quelle: "Sahih Muslim, Nr. 1763 (ʿUmar ibn al-Chaṭṭāb)"},
 {text: "8:32–33: das Gebet Abū Dschahls: „O Allah, wenn dies die Wahrheit von Dir ist, so lass Steine vom Himmel auf uns regnen.“", quelle: "Sahih al-Buchari, Nr. 4648; Sahih Muslim, Nr. 2796"},
 {text: "8:1: der Streit über die Verteilung der Beute nach Badr; Saʿd ibn Abī Waqqāṣ berichtet in diesem Zusammenhang über ein Schwert, das er für sich wollte.", quelle: "Sahih Muslim, Nr. 1748; Sunan Abū Dāwūd, Nr. 2737"}
],
begriffe: [
 {arab: "الْأَنفَال", tr: "al-anfāl", wurzel: "n-f-l", erkl: "Die Beute bzw. die Zugaben – von nafl, das Zusätzliche (daher auch nāfila, das freiwillige Gebet). Die Beute ist eine Zugabe von Allah, nicht das Ziel des Kampfes."},
 {arab: "وَجِلَتْ", tr: "wadschilat", wurzel: "w-dsch-l", erkl: "„Sie ängstigen sich / erbeben“ (8:2) – das Herz des Gläubigen bewegt sich, wenn Allah erwähnt wird. Kein lähmender Schrecken, sondern ehrfürchtige Wachheit."},
 {arab: "وَمَا رَمَيْتَ إِذْ رَمَيْتَ", tr: "wa-mā ramaita idh ramait", wurzel: "r-m-y", erkl: "„Nicht du hast geworfen, als du warfst“ (8:17) – der Prophet ﷺ warf eine Handvoll Sand gegen das feindliche Heer; Allah ließ sie in die Augen der Feinde gelangen. Der Mensch handelt, das Ergebnis kommt von Allah."},
 {arab: "يَوْم الْفُرْقَان", tr: "yaum al-furqān", wurzel: "f-r-q", erkl: "„Der Tag der Unterscheidung“ (8:41) – Badr, der Tag, an dem Wahrheit und Falschheit sichtbar getrennt wurden. Vgl. al-Furqān als Name des Korans (Lektion 42)."},
 {arab: "وَلَا تَنَازَعُوا فَتَفْشَلُوا", tr: "wa-lā tanāzaʿū fa-tafschalū", wurzel: "n-z-ʿ / f-sch-l", erkl: "„Streitet nicht miteinander, sonst verzagt ihr und eure Kraft schwindet“ (8:46). Streit ist im Koran eine Ursache der Niederlage – eine Lehre, die sich bei Uḥud bestätigte (Lektion 89)."},
 {arab: "السَّلْم", tr: "as-salm", wurzel: "s-l-m", erkl: "Frieden (8:61): „Wenn sie sich dem Frieden zuneigen, so neige auch du dich ihm zu und verlass dich auf Allah.“ Der Frieden ist kein Zeichen von Schwäche, sondern ein Gebot, sobald der Gegner ihn ernsthaft anbietet."},
 {arab: "خُمُس", tr: "chumus", wurzel: "ch-m-s", erkl: "Das Fünftel (8:41) – ein Fünftel der Kriegsbeute gehört Allah und dem Gesandten, den Verwandten, Waisen, Armen und Reisenden. Ein früher Sozialtopf aus dem Kriegsertrag."}
],
tafsir: [
 {vers: "Verse 1–4", text: "„Sie fragen dich nach der Beute. Sag: Die Beute gehört Allah und dem Gesandten. So fürchtet Allah und bringt die Beziehungen zwischen euch in Ordnung (aṣliḥū dhāta bainikum).“ Ibn Kathīr: Vor jeder Verteilungsregel kommt die Herzensregel – Frieden untereinander ist wichtiger als Beute. Dann das Profil der Gläubigen: Herzen, die bei Allahs Erwähnung erbeben, Glaube, der durch die Verse wächst, Tawakkul, Gebet und Spenden – „das sind die wahrhaft Gläubigen“."},
 {vers: "Verse 5–19", text: "Die Erzählung von Badr aus Allahs Sicht: Manche Gläubigen wollten nicht in den Kampf, „als würden sie in den Tod getrieben“. Allah versprach eine der beiden Gruppen. Dann die Hilfen: die Engel (8:9–10), der Schlaf als Ruhe in der Nacht vor der Schlacht, der Regen, der reinigt, die Herzen stärkt und den Sand festigt (8:11), und die Eingebung an die Engel: „Ich bin mit euch, so festigt die, die glauben“ (8:12, siehe Brennpunkte). Das Verbot, den Feinden im Kampf den Rücken zu kehren (8:15–16), außer zur Taktik. Und 8:17: „Nicht ihr habt sie getötet, sondern Allah hat sie getötet; und nicht du hast geworfen …“ As-Saʿdī: Der Sieg ist Allahs Werk, damit niemand hochmütig wird."},
 {vers: "Verse 20–40", text: "Aufruf zum Gehorsam: „Antwortet Allah und dem Gesandten, wenn er euch zu dem ruft, was euch Leben gibt“ (8:24) – der Islam als Leben für das Herz. „Hütet euch vor einer Prüfung, die nicht nur die Ungerechten unter euch trifft“ (8:25). Verbot des Verrats an Allah, dem Gesandten und den anvertrauten Gütern (8:27). „Wenn ihr Allah fürchtet, gibt Er euch ein Unterscheidungsvermögen (furqān)“ (8:29) – Taqwā schärft den Blick. Dann der Rückblick auf die Hidschra: Die Mekkaner planten, den Propheten ﷺ festzusetzen, zu töten oder zu vertreiben, „doch Allah plant, und Allah ist der beste Planer“ (8:30; vgl. ruwaidā, Lektion 36). Abū Dschahls Gebet um Steinregen und Allahs Antwort: Er straft sie nicht, solange du unter ihnen bist und solange sie um Vergebung bitten (8:32–33). Und die offene Tür: „Sag denen, die ungläubig sind: Wenn sie aufhören, wird ihnen das Vergangene vergeben“ (8:38)."},
 {vers: "Verse 41–54", text: "Das Fünftel der Beute (8:41). Die Ausgangslage am Tag von Badr: Die Muslime am näheren Talrand, die Feinde am ferneren, die Karawane unterhalb – „hättet ihr euch verabredet, wärt ihr wegen der Verabredung uneins geworden“, aber Allah wollte eine Sache entscheiden (8:42). Die Kampfregel: „Wenn ihr auf eine Schar trefft, so steht fest und gedenkt Allahs viel … und streitet nicht miteinander, sonst verzagt ihr und eure Kraft schwindet; und seid geduldig“ (8:45–46). Warnung vor dem Auszug aus Hochmut und Prahlerei, wie die Mekkaner ihn machten (8:47). Und ein großes Gesetz der Geschichte: „Allah ändert eine Gnade, die Er einem Volk gewährt hat, nicht, bis sie ändern, was in ihnen selbst ist“ (8:53)."},
 {vers: "Verse 55–66", text: "Über vertragsbrüchige Gegner: Wer seinen Vertrag immer wieder bricht, wird hart behandelt; „und wenn du von einem Volk Verrat befürchtest, so kündige ihnen (den Vertrag) gleichermaßen auf (fa-nbidh ilaihim ʿalā sawāʾ)“ (8:58) – öffentlich und offen, nicht heimlich. Die Gelehrten leiten daraus ab: Auch gegenüber einem Feind ist ein Überraschungsangriff während eines bestehenden Vertrags verboten. Dann 8:60: „Bereitet für sie vor, was ihr an Kraft vermögt“ – Abschreckung, damit niemand angreift. Und unmittelbar danach 8:61: „Wenn sie sich dem Frieden zuneigen, so neige auch du dich ihm zu.“ Ibn Kathīr verweist auf Ḥudaibiya: Der Prophet ﷺ nahm den Frieden an, obwohl die Bedingungen hart erschienen. Die Verse 65–66 legen fest, dass die Muslime auch gegen eine Übermacht standhaft sein sollen, und erleichtern die Pflicht danach wegen ihrer Schwäche."},
 {vers: "Verse 67–75", text: "Die Gefangenen von Badr: Der Prophet ﷺ beriet sich; Abū Bakr empfahl Lösegeld und Milde, ʿUmar Härte; der Prophet ﷺ entschied sich für das Lösegeld. Die Verse 67–69 tadeln, dass man sich in diesem frühen Stadium an Gütern des Diesseits orientierte, und erlauben dennoch den Gebrauch der Beute (Sahih Muslim, Nr. 1763). Dann eine Botschaft an die Gefangenen selbst: „Wenn Allah in euren Herzen etwas Gutes weiß, wird Er euch Besseres geben als das, was euch genommen wurde, und euch vergeben“ (8:70). Schluss: die Verbundenheit (walāya) zwischen Auswanderern und Helfern, die neue Bruderschaft im Glauben – und die Pflicht, Verträge auch dann einzuhalten, wenn Muslime anderswo um Hilfe bitten, solange ein Vertrag mit deren Gegnern besteht (8:72)."}
],
ahadith: [
 {text: "Das Gebet des Propheten ﷺ bei Badr: „O Allah, erfülle mir, was Du mir versprochen hast … wenn diese Schar vernichtet wird, wirst Du auf der Erde nicht angebetet“ – und die Beratung über die Gefangenen.", quelle: "Sahih Muslim, Nr. 1763"},
 {text: "„Bereitet für sie vor, was ihr an Kraft vermögt“ (8:60): „Wahrlich, die Kraft ist das Schießen, wahrlich, die Kraft ist das Schießen.“", quelle: "Sahih Muslim, Nr. 1917"},
 {text: "Abū Dschahl betete: „O Allah, wenn dies die Wahrheit von Dir ist, so lass Steine vom Himmel auf uns regnen“ – da kam 8:33 herab.", quelle: "Sahih al-Buchari, Nr. 4648; Sahih Muslim, Nr. 2796"}
],
hanafi: "(1) Das Fünftel der Beute (8:41) und die Verteilung der übrigen vier Fünftel unter den Kämpfern ist Sache der Staatsführung. Ein bekannter Schulunterschied: Nach Abū Ḥanīfa erhält der Reiter zwei Anteile (einen für sich, einen für das Pferd) und der Fußkämpfer einen; nach seinen Schülern Abū Yūsuf und Muḥammad und der Mehrheit erhält der Reiter drei. (2) Zu 8:58: Die hanafitischen Juristen (u. a. as-Sarachsī im Kommentar zu asch-Schaibānīs Siyar) leiten daraus ab, dass ein Vertrag mit Nichtmuslimen nur durch offene Kündigung beendet werden darf und ein Angriff vor der Kündigung Verrat (ġadr) ist. (3) Zu 8:61: Ein Waffenstillstand oder Friedensvertrag (muwādaʿa) ist erlaubt, wenn er im Interesse der Muslime liegt; Entscheidung und Abschluss liegen bei der legitimen Führung, nicht bei Einzelnen oder Gruppen (vgl. die Brennpunkt-Verse).",
umsetzung: [
 "Bring die Beziehungen zwischen dir und anderen in Ordnung (8:1): Wenn du mit jemandem wegen Geld, Erbe oder Besitz im Streit bist, mach diese Woche den ersten Schritt zur Versöhnung.",
 "Prüfe dein Herz nach 8:2: Erbebt es bei Allahs Erwähnung? Wenn nicht, beginne mit langsamem, bewusstem Hören des Korans.",
 "Lerne aus 8:17 Demut im Erfolg: Nach jedem Erfolg (Prüfung, Projekt, Sieg) sage al-ḥamdu lillāh und erinnere dich: Nicht ich habe geworfen.",
 "Mach 8:53 zu deinem Veränderungs-Vers: Wenn du willst, dass sich etwas in deinem Leben ändert, beginne bei dir selbst.",
 "Halte Absprachen und Verträge ein, auch mit Menschen, mit denen du im Konflikt bist – das ist der Geist von 8:58 und 8:72."
]
},

// ───────────────────────── Lektion 89: Āl ʿImrān ─────────────────────────
{
sure: 3, offb: 89, name: "Āl ʿImrān", arab: "سُورَةُ آلِ عِمْرَانَ", de: "Die Familie ʿImrāns", verse: 200, ort: "Medina",
zeit: "Medinensisch – große Teile nach der Schlacht von Uḥud (Schawwāl 3 n. H., 625 n. Chr.) und im Zusammenhang mit der christlichen Delegation aus Nadschrān",
kurz: "Āl ʿImrān ist die Schwestersure von Al-Baqara – zusammen nannte der Prophet ﷺ sie „die beiden Leuchtenden“. Sie hat zwei große Themen. Das erste ist das Gespräch mit den Christen: Eine Delegation aus Nadschrān kam nach Medina, und die Sure erzählt die Geschichte der Familie ʿImrāns – Maryam, Zakariyyā, Yaḥyā und ʿĪsā – aus islamischer Sicht und lädt zu einem gemeinsamen Wort ein: „dass wir niemandem außer Allah dienen“. Das zweite ist die Schlacht von Uḥud: Nach dem Sieg von Badr erlitten die Muslime hier eine schmerzhafte Niederlage, weil Bogenschützen ihren Posten verließen. Die Sure verarbeitet diese Niederlage mit Ehrlichkeit und Trost: „Verliert nicht den Mut und seid nicht traurig, ihr werdet die Oberhand haben, wenn ihr gläubig seid.“ Sie lehrt, Fehler einzugestehen, Führung mit Milde und Beratung auszuüben und im Leid zu sagen: „Allah genügt uns, und Er ist der beste Sachwalter.“",
schluessel: {arab: "إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ", ueb: "In der Erschaffung der Himmel und der Erde und im Wechsel von Nacht und Tag sind wahrlich Zeichen für die Verständigen.", ref: "3:190"},
kontext: ["Nach Badr sammelte Mekka ein Heer von etwa dreitausend Mann und zog im Jahr 3 n. H. gegen Medina. Am Berg Uḥud stellte der Prophet ﷺ fünfzig Bogenschützen auf einen Hügel und befahl ihnen, ihren Posten unter keinen Umständen zu verlassen. Die Muslime waren zuerst siegreich; als die Bogenschützen die Feinde fliehen sahen, verließen die meisten den Hügel, um Beute zu sammeln. Chālid ibn al-Walīd (damals noch Gegner) umging den Berg und griff von hinten an. Etwa siebzig Muslime fielen, darunter Ḥamza, der Onkel des Propheten ﷺ; der Prophet ﷺ selbst wurde verletzt (Sahih al-Buchari, Nr. 4043).",
"Fast zur selben Zeit kam eine christliche Delegation aus Nadschrān (im Süden der Arabischen Halbinsel) nach Medina, um über ʿĪsā zu sprechen. Der Prophet ﷺ empfing sie, und die ersten rund achtzig Verse der Sure gehen auf diese Begegnung ein: Sie würdigen Maryam als auserwählte Frau, erzählen ʿĪsās wundersame Geburt und seine Zeichen, bestreiten aber seine Göttlichkeit: „Das Gleichnis ʿĪsās ist bei Allah wie das Gleichnis Ādams: Er erschuf ihn aus Erde“ (3:59). Am Ende schlug der Prophet ﷺ eine gegenseitige Verwünschung (mubāhala) vor; die Delegation lehnte ab und schloss einen Vertrag (Sahih al-Buchari, Nr. 4380; Sahih Muslim, Nr. 2404).",
"Die Sure enthält auch die Pflicht der Pilgerfahrt: „Und Allah steht es gegenüber den Menschen zu, dass sie die Pilgerfahrt zum Haus unternehmen – wer dazu einen Weg zu finden vermag“ (3:97). Und sie endet mit zehn Versen über die „Verständigen“ (ulū l-albāb), die der Prophet ﷺ nachts beim Aufstehen zum Gebet rezitierte (Sahih al-Buchari, Nr. 4569)."],
asbab: [
 {text: "Die Delegation aus Nadschrān und der Vers der gegenseitigen Verwünschung (3:61); der Prophet ﷺ rief ʿAlī, Fāṭima, al-Ḥasan und al-Ḥusain.", quelle: "Sahih al-Buchari, Nr. 4380; Sahih Muslim, Nr. 2404"},
 {text: "3:92 („Ihr werdet die Frömmigkeit nicht erlangen, bis ihr von dem ausgebt, was ihr liebt“): Abū Ṭalḥa spendete daraufhin seinen liebsten Garten Bairuḥāʾ.", quelle: "Sahih al-Buchari, Nr. 1461; Sahih Muslim, Nr. 998"},
 {text: "3:128 („Dir steht in der Angelegenheit nichts zu“): nach der Verletzung des Propheten ﷺ bei Uḥud, als er sagte: „Wie soll ein Volk erfolgreich sein, das seinen Propheten verletzt?“", quelle: "Sahih Muslim, Nr. 1791"},
 {text: "3:144 („Muhammad ist nur ein Gesandter“): Bei Uḥud verbreitete sich das Gerücht, der Prophet ﷺ sei getötet worden; beim tatsächlichen Tod des Propheten ﷺ rezitierte Abū Bakr diesen Vers, um die Gemeinde zu festigen.", quelle: "Sahih al-Buchari, Nr. 1241–1242 und 4454"},
 {text: "3:173 („Allah genügt uns, und Er ist der beste Sachwalter“): gesprochen von den Gläubigen nach Uḥud, als man ihnen die Rückkehr der Feinde androhte – so sprach auch Ibrāhīm, als er ins Feuer geworfen wurde.", quelle: "Sahih al-Buchari, Nr. 4563"}
],
begriffe: [
 {arab: "مُحْكَمَات / مُتَشَابِهَات", tr: "muḥkamāt / mutaschābihāt", wurzel: "ḥ-k-m / sch-b-h", erkl: "Eindeutige und mehrdeutige Verse (3:7). Die eindeutigen sind „die Mutter des Buches“, an der die mehrdeutigen gemessen werden. Wer nur die mehrdeutigen herauspickt, um Verwirrung zu stiften, folgt einer Krankheit im Herzen – eine Grundregel auch für den Umgang mit den Brennpunkt-Versen."},
 {arab: "الْمُبَاهَلَة", tr: "al-mubāhala", wurzel: "b-h-l", erkl: "Gegenseitige Verwünschung (3:61): Beide Seiten bitten Allah, Seinen Fluch auf die Lügner zu legen. Ein Zeichen äußerster Gewissheit des Propheten ﷺ über die Wahrheit seiner Botschaft über ʿĪsā."},
 {arab: "كَلِمَةٍ سَوَاءٍ", tr: "kalimatin sawāʾ", wurzel: "s-w-y", erkl: "„Ein gleiches (gemeinsames) Wort“ (3:64): dass wir nur Allah dienen, Ihm nichts beigesellen und einander nicht zu Herren neben Allah nehmen. Der Prophet ﷺ schrieb diesen Vers in seinem Brief an den byzantinischen Kaiser Herakleios (Sahih al-Buchari, Nr. 7)."},
 {arab: "حَبْلِ اللَّه", tr: "ḥabl Allāh", wurzel: "ḥ-b-l", erkl: "„Das Seil Allahs“ (3:103): „Haltet alle fest am Seil Allahs und spaltet euch nicht.“ Nach den Mufassirūn der Koran, der Islam bzw. die Gemeinschaft. Ein Seil verbindet und rettet – wer es loslässt, fällt."},
 {arab: "الشُّورَىٰ", tr: "asch-schūrā", wurzel: "sch-w-r", erkl: "Beratung (3:159): „Und berate dich mit ihnen in der Angelegenheit.“ Bemerkenswert: Der Befehl kommt direkt nach Uḥud, wo die Beratung (in der Stadt bleiben oder hinausziehen) zu einer Entscheidung geführt hatte, die mit Verlusten endete. Trotzdem: weiter beraten."},
 {arab: "أُولِي الْأَلْبَاب", tr: "ulī l-albāb", wurzel: "l-b-b", erkl: "„Die Verständigen“ – lubb ist der Kern einer Frucht: Menschen, die zum Kern der Dinge vordringen. Sie gedenken Allahs stehend, sitzend und liegend und denken über die Schöpfung nach (3:190–191)."},
 {arab: "حَسْبُنَا اللَّه", tr: "ḥasbunā llāh", wurzel: "ḥ-s-b", erkl: "„Allah genügt uns“ (3:173) – das Wort des Vertrauens in äußerster Bedrohung. Die vollständige Formel: ḥasbunā llāhu wa-niʿma l-wakīl, „und Er ist der beste Sachwalter“."}
],
tafsir: [
 {vers: "Verse 1–32: Offenbarung und Grundlagen", text: "Allah, der Lebendige, der Beständige, hat das Buch mit der Wahrheit herabgesandt, wie zuvor Tora und Evangelium. Vers 7 teilt die Verse in eindeutige und mehrdeutige und beschreibt die Haltung der fest im Wissen Gegründeten: „Wir glauben daran; alles ist von unserem Herrn.“ Dazu ihr Gebet: „Unser Herr, lass unsere Herzen nicht abschweifen, nachdem Du uns rechtgeleitet hast“ (3:8). Dann eine Erinnerung an Badr als Zeichen (3:13), die Aufzählung dessen, was den Menschen anzieht – Frauen, Söhne, Gold und Silber, Pferde, Vieh und Ackerland – „das ist der Nießbrauch des diesseitigen Lebens“ (3:14), und 3:19: „Die Religion bei Allah ist der Islam.“ Am Ende: „Sag: Wenn ihr Allah liebt, so folgt mir, dann liebt euch Allah“ (3:31) – Liebe zu Allah zeigt sich in der Befolgung der Sunna."},
 {vers: "Verse 33–63: die Familie ʿImrāns", text: "Allah erwählte Ādam, Nūḥ, die Familie Ibrāhīms und die Familie ʿImrāns. Die Frau ʿImrāns gelobt ihr Kind Allah; es wird ein Mädchen, Maryam, und sie stellt sie unter Allahs Schutz. Zakariyyā findet bei Maryam Versorgung, die von Allah kommt, und bittet selbst im hohen Alter um ein Kind – Yaḥyā wird ihm geschenkt. Die Engel verkünden Maryam: „Allah hat dich auserwählt und rein gemacht und dich vor den Frauen der Welten erwählt“ (3:42). Dann die Verkündigung ʿĪsās, seine Wunder mit Allahs Erlaubnis, sein Ruf zu Allah und seine Jünger. Kernaussage gegenüber den Christen: „Das Gleichnis ʿĪsās ist bei Allah wie das Gleichnis Ādams“ (3:59) – wer Ādam ohne Vater und Mutter erschuf, kann ʿĪsā ohne Vater erschaffen, ohne dass er göttlich wäre. Dann der Vorschlag der mubāhala (3:61)."},
 {vers: "Verse 64–120: das gemeinsame Wort und die beste Gemeinschaft", text: "3:64, das gemeinsame Wort an die Schriftbesitzer. Ibrāhīm war weder Jude noch Christ, sondern ein aufrichtiger Muslim (3:67). Warnung davor, die Wahrheit mit Falschem zu vermengen. „Wer eine andere Religion als den Islam sucht, von dem wird sie nicht angenommen werden“ (3:85). „Ihr werdet die Frömmigkeit nicht erlangen, bis ihr von dem ausgebt, was ihr liebt“ (3:92) – Abū Ṭalḥa gab daraufhin seinen schönsten Garten. Die Pilgerfahrt (3:97). Dann die Grundsätze der Gemeinschaft: „Fürchtet Allah, wie Er gefürchtet werden soll, und sterbt nicht anders denn als Muslime“ (3:102), das Seil Allahs (3:103), die Erinnerung, dass Allah die Herzen der verfeindeten Aus und Chazradsch verband, und der Auftrag: „Ihr seid die beste Gemeinschaft, die für die Menschen hervorgebracht wurde: Ihr gebietet das Rechte, verbietet das Verwerfliche und glaubt an Allah“ (3:110). Ibn Kathīr: Die Bestheit hängt an den Bedingungen, nicht an der Herkunft."},
 {vers: "Verse 121–148: Uḥud – Fehler und Lehre", text: "Rückblick auf den Morgen von Uḥud, als der Prophet ﷺ die Gläubigen aufstellte (3:121). Erinnerung an Badr, wo Allah half, als sie schwach waren (3:123). Mitten in der Schlachtschilderung ein Abschnitt über Zins (3:130), Gehorsam und Paradies: „Eilt zur Vergebung von eurem Herrn und zu einem Garten, so breit wie Himmel und Erde, bereitet für die Gottesfürchtigen – die in Freude und Leid ausgeben, ihren Zorn zurückhalten und den Menschen verzeihen“ (3:133–134). Und für die, die gesündigt haben: Sie gedenken Allahs, bitten um Vergebung „und verharren nicht wissentlich in dem, was sie getan haben“ (3:135). Dann der Trost: „Verliert nicht den Mut und seid nicht traurig“ (3:139). „Wenn euch eine Wunde trifft, so hat eine gleiche Wunde auch die (anderen) Leute getroffen. Diese Tage lassen Wir unter den Menschen wechseln“ (3:140). Und 3:144: „Muhammad ist nur ein Gesandter … Wenn er stirbt oder getötet wird, werdet ihr euch dann auf den Fersen umkehren?“"},
 {vers: "Verse 149–175: Ursachen der Niederlage, Milde und Vertrauen", text: "Die ehrliche Analyse: Allah hatte Sein Versprechen gehalten, „bis ihr verzagtet, über die Sache strittet und ungehorsam wurdet, nachdem Er euch gezeigt hatte, was ihr liebtet. Unter euch gab es welche, die das Diesseits wollten, und welche, die das Jenseits wollten“ (3:152). Und doch: „Allah hat euch bereits verziehen.“ Dann der wichtigste Führungsvers des Korans (3:159): „Durch Barmherzigkeit von Allah bist du mild zu ihnen gewesen. Wärst du schroff und hartherzig gewesen, wären sie um dich auseinandergelaufen. So verzeih ihnen, bitte für sie um Vergebung und berate dich mit ihnen; und wenn du entschlossen bist, so verlass dich auf Allah.“ Al-Qurṭubī: Nach einem Fehler der Gefährten befiehlt Allah nicht Strafe, sondern Verzeihung, Fürbitte und weitere Beratung. Dann die Märtyrer von Uḥud: „Halte die nicht für tot, die auf dem Weg Allahs getötet wurden; vielmehr sind sie lebendig bei ihrem Herrn und werden versorgt“ (3:169). Und die Gläubigen, die trotz Wunden zur Verfolgung des Feindes auszogen und sagten: „Allah genügt uns“ (3:173)."},
 {vers: "Verse 176–189: Prüfung, Tod und Geiz", text: "Trost gegen die Eile der Ungläubigen in den Unglauben. „Jede Seele wird den Tod kosten, und ihr werdet euren Lohn am Tag der Auferstehung voll erhalten. Wer vom Feuer weggerückt und ins Paradies eingelassen wird, hat Erfolg. Das diesseitige Leben ist nur trügerischer Nießbrauch“ (3:185). „Ihr werdet gewiss an eurem Besitz und an euch selbst geprüft werden, und ihr werdet viel Verletzendes hören … Wenn ihr aber geduldig und gottesfürchtig seid, so ist das eine Sache fester Entschlossenheit“ (3:186). Warnung an die, die mit Allahs Gaben geizen (3:180), und an die, die das Wissen der Schrift verbargen (3:187)."},
 {vers: "Verse 190–200: die Verständigen", text: "„In der Erschaffung der Himmel und der Erde und im Wechsel von Nacht und Tag sind Zeichen für die Verständigen, die Allahs gedenken, stehend, sitzend und auf der Seite liegend, und über die Erschaffung der Himmel und der Erde nachdenken: Unser Herr, Du hast dies nicht umsonst erschaffen. Gepriesen seist Du! So bewahre uns vor der Strafe des Feuers.“ Es folgen ihre Gebete und Allahs Antwort: „Ich lasse kein Werk eines Handelnden unter euch verloren gehen, ob Mann oder Frau – die einen von euch sind von den anderen“ (3:195) – eine klare Aussage über die Gleichwertigkeit von Mann und Frau vor Allah. Schlussvers: „O ihr, die ihr glaubt, seid geduldig, wetteifert in Geduld, seid standhaft und fürchtet Allah, auf dass es euch wohl ergehe“ (3:200). Ibn ʿAbbās berichtet, dass der Prophet ﷺ diese Verse nachts beim Aufwachen rezitierte (Sahih al-Buchari, Nr. 4569)."}
],
ahadith: [
 {text: "ʿĀʾischa: Der Prophet ﷺ rezitierte 3:7 und sagte: „Wenn ihr die seht, die dem Mehrdeutigen daraus folgen, dann sind das die, die Allah genannt hat – so hütet euch vor ihnen.“", quelle: "Sahih al-Buchari, Nr. 4547; Sahih Muslim, Nr. 2665"},
 {text: "„Lest den Koran, denn er wird am Tag der Auferstehung als Fürsprecher für seine Leute kommen. Lest die beiden Leuchtenden: Al-Baqara und Āl ʿImrān …“", quelle: "Sahih Muslim, Nr. 804"},
 {text: "Der Brief des Propheten ﷺ an Herakleios mit dem Vers 3:64: „Sag: O Leute der Schrift, kommt zu einem gemeinsamen Wort …“", quelle: "Sahih al-Buchari, Nr. 7"},
 {text: "Abū Ṭalḥa spendete nach 3:92 seinen liebsten Besitz, den Garten Bairuḥāʾ; der Prophet ﷺ riet ihm, ihn unter seinen Verwandten zu verteilen.", quelle: "Sahih al-Buchari, Nr. 1461; Sahih Muslim, Nr. 998"},
 {text: "„Allah genügt uns, und Er ist der beste Sachwalter“ sagte Ibrāhīm, als er ins Feuer geworfen wurde, und sagte Muhammad ﷺ, als man ihm sagte: „Die Leute haben sich gegen euch versammelt.“", quelle: "Sahih al-Buchari, Nr. 4563"},
 {text: "Ibn ʿAbbās übernachtete bei seiner Tante Maimūna; der Prophet ﷺ wachte nachts auf, rieb den Schlaf aus dem Gesicht und rezitierte die zehn letzten Verse von Āl ʿImrān, dann betete er.", quelle: "Sahih al-Buchari, Nr. 4569 (vgl. 183); Sahih Muslim, Nr. 763"}
],
hanafi: "(1) Pilgerfahrt (3:97): Sie ist farḍ einmal im Leben für jeden mündigen, freien, gesunden Muslim, der die Reisemittel über seinen Grundbedarf und den Unterhalt seiner Familie hinaus besitzt und dessen Weg sicher ist. Für Frauen setzt die hanafitische Schule zusätzlich die Begleitung durch einen Ehemann oder Maḥram voraus, wenn die Entfernung die Reisestrecke (Safar) erreicht. Ob die Pflicht sofort zu erfüllen ist, sobald die Bedingungen vorliegen: Nach Abū Yūsuf (und nach einer Überlieferung auch Abū Ḥanīfa) ja – sie sofort zu verschieben, ist sündhaft; nach Muḥammad asch-Schaibānī darf sie aufgeschoben werden, solange man sie vor dem Tod verrichtet. Die vorsichtige und in der Fatwa verbreitete Haltung: nicht ohne Grund aufschieben. (2) Zins (3:130): Das Verbot des „mehrfach verdoppelten“ Zinses wird von den Hanafiten nicht als Erlaubnis kleinerer Zinsen verstanden – das Verbot gilt für jeden Zins (vgl. 2:275–279, Lektion 87).",
umsetzung: [
 "Lies die zehn letzten Verse (3:190–200) beim nächtlichen Aufwachen oder vor dem Fadschr – so wie der Prophet ﷺ (Buchari 4569).",
 "Übe 3:134 eine Woche lang bewusst: Zorn zurückhalten und den Menschen verzeihen. Halte abends fest, wann es dir gelungen ist.",
 "Wende 3:159 in deiner Familie, im Unterricht oder im Team an: Milde statt Schroffheit, Verzeihung nach Fehlern, Beratung vor Entscheidungen.",
 "Sprich in Angst oder Bedrohung bewusst ḥasbunā llāhu wa-niʿma l-wakīl (3:173) – und handle dann mit Vertrauen weiter.",
 "Gib nach 3:92 einmal etwas, das du wirklich liebst – nicht nur das Übriggebliebene.",
 "Wenn du die Pilgerfahrt finanziell und körperlich verrichten kannst, plane sie konkret – nach hanafitischer Vorsicht nicht ohne Grund aufschieben."
]
},

// ───────────────────────── Lektion 90: Al-Aḥzāb ─────────────────────────
{
sure: 33, offb: 90, name: "Al-Aḥzāb", arab: "سُورَةُ الْأَحْزَابِ", de: "Die Verbündeten", verse: 73, ort: "Medina",
zeit: "Medinensisch – um die Grabenschlacht (Schawwāl/Dhū l-Qaʿda 5 n. H., 627 n. Chr.) und die Neuordnung des Familienlebens im Haus des Propheten ﷺ",
kurz: "Im Jahr 5 n. H. verbündeten sich die Quraisch mit mehreren arabischen Stämmen und zogen mit rund zehntausend Mann gegen Medina – die „Verbündeten“ (al-aḥzāb). Auf den Rat Salmāns des Persers hoben die Muslime einen Graben aus. Die Belagerung dauerte Wochen; Hunger, Kälte und Angst machten die Lage verzweifelt, „als die Blicke abschweiften und die Herzen bis zur Kehle stiegen“. Die Heuchler suchten Ausreden, die Gläubigen sagten: „Das ist, was Allah und Sein Gesandter uns versprochen haben.“ Ein Sturm und unsichtbare Heerscharen beendeten die Belagerung. In dieser Krise steht der Vers: „Im Gesandten Allahs habt ihr ein schönes Vorbild.“ Der zweite Teil der Sure ordnet das Familienleben neu: Adoptivkinder behalten den Namen ihrer Väter, die Frauen des Propheten ﷺ erhalten besondere Anweisungen, Männer und Frauen werden mit zehn gleichen Tugenden gewürdigt, Muhammad ﷺ wird als „Siegel der Propheten“ benannt, und Allah und Seine Engel sprechen Segen über den Propheten ﷺ – mit dem Aufruf an alle Gläubigen, es ebenso zu tun.",
schluessel: {arab: "لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا", ueb: "Ihr habt ja im Gesandten Allahs ein schönes Vorbild, für einen jeden, der auf Allah und den Jüngsten Tag hofft und Allahs viel gedenkt.", ref: "33:21"},
kontext: ["Die Grabenschlacht (al-Chandaq) war die größte Bedrohung, die Medina je erlebte. Etwa dreitausend Muslime standen gegen ein Bündnis von rund zehntausend. Der Prophet ﷺ grub selbst mit, trug Erde, bis sein Bauch staubbedeckt war, und sang mit den Gefährten Verse (Sahih al-Buchari, Nr. 2837). Als ein harter Felsen auftauchte, schlug er selbst darauf, bis er zerfiel (Sahih al-Buchari, Nr. 4101). Während der Belagerung brach der jüdische Stamm Banū Quraiẓa seinen Vertrag mit Medina und öffnete sich den Angreifern – damit war die Stadt von innen bedroht.",
"Die Sure schildert die Reaktionen der Menschen sehr genau: Die Heuchler sagten: „Allah und Sein Gesandter haben uns nur Trug versprochen“ und baten um Erlaubnis, nach Hause zu gehen, weil ihre Häuser angeblich ungeschützt seien (33:12–13). Die Gläubigen dagegen sagten beim Anblick der Verbündeten: „Das ist, was Allah und Sein Gesandter uns versprochen haben“ (33:22). Nach dem Abzug der Verbündeten wurde über die vertragsbrüchigen Banū Quraiẓa nach dem Urteil Saʿd ibn Muʿādhs entschieden, dem sie sich unterworfen hatten (Sahih al-Buchari, Nr. 4121) – ein Urteil nach dem Kriegsrecht der damaligen Zeit wegen Hochverrats während einer Belagerung, das in der Geschichtsschreibung ausführlich diskutiert wird.",
"Der zweite Teil der Sure betrifft das Familienleben. Der Prophet ﷺ hatte Zaid ibn Ḥāritha vor seiner Sendung als Sohn angenommen; man nannte ihn „Zaid ibn Muhammad“. Die Sure beendet die Adoption im Sinne einer Namens- und Abstammungsänderung: „Nennt sie nach ihren Vätern“ (33:5). Später heiratete Zaid Zainab bint Dschaḥsch, die Ehe scheiterte, und Allah ordnete an, dass der Prophet ﷺ Zainab heiratet – um zu zeigen, dass die geschiedene Frau eines Adoptivsohnes nicht wie die eines leiblichen Sohnes behandelt wird (33:37). In diesem Zusammenhang steht 33:40: „Muhammad ist nicht der Vater irgendeines eurer Männer, sondern der Gesandte Allahs und das Siegel der Propheten.“"],
asbab: [
 {text: "33:23 („Unter den Gläubigen gibt es Männer, die wahr gemacht haben, wozu sie sich Allah gegenüber verpflichtet hatten“): Anas ibn an-Naḍr, der Badr verpasst hatte und bei Uḥud mit über achtzig Wunden fiel.", quelle: "Sahih al-Buchari, Nr. 2805; Sahih Muslim, Nr. 1903"},
 {text: "33:28–29: Die Frauen des Propheten ﷺ baten um mehr Unterhalt; Allah ließ ihnen die Wahl zwischen dem Diesseits und Allah, Seinem Gesandten und dem Jenseits – ʿĀʾischa wählte als Erste Allah und Seinen Gesandten.", quelle: "Sahih al-Buchari, Nr. 4785; Sahih Muslim, Nr. 1475"},
 {text: "33:37 (Zaid und Zainab): „… und du verbargst in dir, was Allah offenlegen würde.“ Anas: Wenn der Prophet ﷺ etwas verborgen hätte, dann diesen Vers.", quelle: "Sahih al-Buchari, Nr. 7420"},
 {text: "33:53 (Anstandsregeln im Haus des Propheten ﷺ und der Vorhang): herabgesandt nach dem Hochzeitsessen für Zainab, als einige Gäste zu lange blieben.", quelle: "Sahih al-Buchari, Nr. 4791; Sahih Muslim, Nr. 1428"},
 {text: "33:35: Umm Salama fragte, warum im Koran die Männer erwähnt würden und die Frauen nicht; darauf kam der Vers mit den zehn Tugenden für Männer und Frauen herab.", quelle: "Sunan at-Tirmidhī, Nr. 3211 (hasan); Musnad Aḥmad"}
],
begriffe: [
 {arab: "الْأَحْزَاب", tr: "al-aḥzāb", wurzel: "ḥ-z-b", erkl: "Die Verbündeten/Parteien – das Bündnis der Stämme gegen Medina. Im Koran stehen sie oft für Koalitionen gegen die Wahrheit (vgl. 38:11, Lektion 38). Ihr Bündnis zerbrach an einem Sturm."},
 {arab: "أُسْوَةٌ حَسَنَةٌ", tr: "uswatun ḥasana", wurzel: "ʾ-s-w", erkl: "„Ein schönes Vorbild“ (33:21) – offenbart mitten in der härtesten Krise: Der Prophet ﷺ ist Vorbild nicht nur im Frieden, sondern gerade in Hunger, Angst und Belagerung. Die Bedingung: wer auf Allah und den Jüngsten Tag hofft und viel gedenkt."},
 {arab: "أَدْعِيَاء", tr: "adʿiyāʾ", wurzel: "d-ʿ-w", erkl: "„Angenommene Söhne“ (33:4) – Allah hat eure Adoptivsöhne nicht zu euren leiblichen Söhnen gemacht. Fürsorge für fremde Kinder ist gut und belohnt; nur Name und Abstammung bleiben wahr."},
 {arab: "خَاتَمَ النَّبِيِّين", tr: "chātam an-nabiyyīn", wurzel: "ch-t-m", erkl: "„Das Siegel der Propheten“ (33:40) – das Siegel schließt einen Brief ab: Nach Muhammad ﷺ kommt kein Prophet mehr. Ein Glaubensgrundsatz, über den unter Muslimen Einigkeit herrscht."},
 {arab: "صَلُّوا عَلَيْهِ", tr: "ṣallū ʿalaihi", wurzel: "ṣ-l-w", erkl: "„Sprecht Segen über ihn“ (33:56): „Allah und Seine Engel sprechen Segen über den Propheten. O ihr, die ihr glaubt, sprecht Segen über ihn und grüßt ihn mit gebührendem Gruß.“ Von Allah ist die ṣalāt Lob und Erhöhung, von den Engeln und Gläubigen Bittgebet."},
 {arab: "قَوْلًا سَدِيدًا", tr: "qaulan sadīdā", wurzel: "s-d-d", erkl: "„Ein treffendes, aufrichtiges Wort“ (33:70): „Fürchtet Allah und sagt ein treffendes Wort, dann wird Er eure Taten richtig machen und euch eure Sünden vergeben.“ Richtiges Sprechen führt zu richtigem Handeln."},
 {arab: "الْأَمَانَة", tr: "al-amāna", wurzel: "ʾ-m-n", erkl: "Das anvertraute Gut (33:72): Allah bot es Himmeln, Erde und Bergen an, doch sie weigerten sich aus Angst – „der Mensch aber nahm es auf sich“. Die Amāna ist die Verantwortung der freien Wahl und der Gebote. Ein Schlussvers, der dem Menschen seine Würde und seine Last zeigt."}
],
tafsir: [
 {vers: "Verse 1–8: Grundsätze", text: "„O Prophet, fürchte Allah und gehorche nicht den Ungläubigen und den Heuchlern … folge dem, was dir offenbart wird … und verlass dich auf Allah.“ Dann: „Allah hat keinem Mann zwei Herzen in seiner Brust gemacht“ (33:4) – man kann nicht zwei gegensätzlichen Loyalitäten gleichzeitig folgen. Die Gleichstellung der Ehefrau mit der Mutter (ẓihār) und die Adoption als Abstammungsänderung werden aufgehoben: „Nennt sie nach ihren Vätern; das ist gerechter bei Allah.“ Und 33:6: „Der Prophet steht den Gläubigen näher als sie selbst, und seine Frauen sind ihre Mütter.“ Ibn Kathīr: Die Liebe zum Propheten ﷺ geht der Liebe zu sich selbst vor."},
 {vers: "Verse 9–27: die Grabenschlacht", text: "„Gedenkt der Gunst Allahs an euch, als Heerscharen zu euch kamen und Wir gegen sie einen Wind sandten und Heerscharen, die ihr nicht saht“ (33:9). Die Lage: Sie kamen „von oberhalb und unterhalb von euch, als die Blicke abschweiften und die Herzen bis zur Kehle stiegen und ihr von Allah verschiedene Gedanken hegtet. Dort wurden die Gläubigen geprüft und heftig erschüttert“ (33:10–11). Die Ausreden der Heuchler (33:12–20). Dann 33:21, das schöne Vorbild. Die Gläubigen sagten beim Anblick der Verbündeten: „Das ist, was Allah und Sein Gesandter uns versprochen haben“ – „und es mehrte nur ihren Glauben und ihre Ergebenheit“ (33:22). „Unter den Gläubigen gibt es Männer, die wahr gemacht haben, wozu sie sich Allah gegenüber verpflichtet hatten“ (33:23). „Allah wies die Ungläubigen mit ihrem Groll zurück, ohne dass sie etwas Gutes erlangt hätten“ (33:25). Zu den Banū Quraiẓa (33:26–27) siehe den Kontext oben."},
 {vers: "Verse 28–35: das Haus des Propheten und zehn Tugenden", text: "Die Frauen des Propheten ﷺ erhalten die Wahl: das Diesseits und seinen Schmuck – oder Allah, Seinen Gesandten und das Jenseits; alle wählten Allah und Seinen Gesandten (33:28–29). Dann besondere Anweisungen an sie: Ihr seid nicht wie irgendeine der Frauen; sprecht nicht in weichlicher Weise, bleibt in euren Häusern und stellt euch nicht zur Schau wie in der früheren Unwissenheit, verrichtet das Gebet, gebt die Zakat (33:32–33). „Allah will die Unreinheit von euch fernhalten, ihr Leute des Hauses (ahl al-bait), und euch völlig rein machen“ (33:33). Dann 33:35: Muslimische Männer und Frauen, gläubige Männer und Frauen, gehorsame, wahrhaftige, geduldige, demütige, spendende, fastende, ihre Scham hütende und Allahs viel gedenkende Männer und Frauen – „für sie hat Allah Vergebung und großartigen Lohn bereitet“. As-Saʿdī: Zehn Tugenden, gleich für beide, gleich belohnt."},
 {vers: "Verse 36–48: Gehorsam, Zaid und das Siegel", text: "„Es steht einem gläubigen Mann oder einer gläubigen Frau nicht zu, wenn Allah und Sein Gesandter eine Angelegenheit entschieden haben, in ihrer Angelegenheit eine Wahl zu haben“ (33:36). Dann Zaid und Zainab (33:37): Zaid ist der einzige Gefährte, der im Koran mit Namen genannt wird. Die Ehe des Propheten ﷺ mit Zainab hebt das Tabu der Adoptivsohn-Ehefrau auf. 33:40: Siegel der Propheten. Dann Dhikr: „O ihr, die ihr glaubt, gedenkt Allahs in häufigem Gedenken und preist Ihn morgens und abends. Er ist es, Der über euch Segen spricht, und Seine Engel, um euch aus den Finsternissen ins Licht zu bringen“ (33:41–43). Und die Aufgaben des Propheten ﷺ: Zeuge, Verkünder froher Botschaft, Warner, Rufer zu Allah mit Seiner Erlaubnis und „eine leuchtende Lampe“ (33:45–46)."},
 {vers: "Verse 49–62: Familienrecht, Segensgebet und Bedeckung", text: "Wer eine Frau vor dem Vollzug der Ehe entlässt, für den gibt es keine Wartezeit (33:49). Regeln für die Ehen des Propheten ﷺ (33:50–52). Anstandsregeln für das Haus des Propheten ﷺ: nicht ohne Erlaubnis eintreten, nach dem Essen nicht verweilen, von seinen Frauen etwas nur hinter einem Vorhang erbitten (33:53). Dann 33:56, das Segensgebet über den Propheten ﷺ – der einzige Befehl, bei dem Allah zuerst von Sich selbst und Seinen Engeln sagt, dass sie ihn ausführen. Warnung vor denen, die Allah, Seinen Gesandten und die Gläubigen kränken (33:57–58). Und 33:59, die Anweisung an die Frauen des Propheten ﷺ, seine Töchter und die Frauen der Gläubigen, ihren Überwurf über sich zu ziehen, „damit sie erkannt und nicht belästigt werden“ – ausführlich erklärt in den Brennpunkt-Versen, zusammen mit 24:30–31. Dann eine Warnung an die Heuchler und Unruhestifter in Medina (33:60–62)."},
 {vers: "Verse 63–73: die Stunde, das treffende Wort und die Amāna", text: "Fragen nach der Stunde: Das Wissen darüber ist bei Allah allein (33:63; vgl. Lektion 81). Die Reue der Verführten am Jüngsten Tag, die ihren Großen und Führern folgten (33:66–68). Mahnung, nicht wie die zu sein, die Mūsā kränkten (33:69). Dann 33:70–71: „Fürchtet Allah und sagt ein treffendes Wort, dann wird Er eure Werke richtig machen und euch eure Sünden vergeben. Wer Allah und Seinem Gesandten gehorcht, der erzielt einen großartigen Erfolg.“ Diese Verse rezitierte der Prophet ﷺ in der sogenannten Chuṭbat al-Ḥādscha. Schluss 33:72–73: das anvertraute Gut, das der Mensch auf sich nahm – „er ist sehr ungerecht und sehr töricht“ –, damit Allah die Heuchler bestraft und sich den Gläubigen gnädig zuwendet. Al-Qurṭubī: Die Sure, die mit dem Gehorsam begann, endet mit der Verantwortung, die jeder Mensch trägt."}
],
ahadith: [
 {text: "„Das Gleichnis zwischen mir und den Propheten vor mir ist wie ein Mann, der ein Haus schön baute bis auf die Stelle eines Ziegelsteins … Ich bin dieser Ziegelstein, und ich bin das Siegel der Propheten.“", quelle: "Sahih al-Buchari, Nr. 3535; Sahih Muslim, Nr. 2286"},
 {text: "Kaʿb ibn ʿUdschra: Auf die Frage, wie man Segen über ihn spricht, lehrte der Prophet ﷺ die ṣalāt ibrāhīmiyya: „Allāhumma ṣalli ʿalā Muḥammadin wa-ʿalā āli Muḥammad, kamā ṣallaita ʿalā Ibrāhīma …“", quelle: "Sahih al-Buchari, Nr. 3370; Sahih Muslim, Nr. 406"},
 {text: "„Wer einmal Segen über mich spricht, über den spricht Allah dafür zehnmal Segen.“", quelle: "Sahih Muslim, Nr. 408"},
 {text: "Jābir: Beim Ausheben des Grabens stieß man auf einen harten Felsen; der Prophet ﷺ, der vor Hunger einen Stein an den Bauch gebunden hatte, schlug darauf, bis er wie Sand zerfiel.", quelle: "Sahih al-Buchari, Nr. 4101"},
 {text: "Anas ibn an-Naḍr fiel bei Uḥud mit über achtzig Wunden; die Gefährten sahen in ihm einen der Männer aus 33:23.", quelle: "Sahih al-Buchari, Nr. 2805"}
],
hanafi: "(1) Segensgebet (33:56): Nach hanafitischer Schule ist es einmal im Leben farḍ, Segen über den Propheten ﷺ zu sprechen. Im letzten Taschahhud des Gebets ist die ṣalāt ibrāhīmiyya Sunna – anders als bei den Schāfiʿiten, bei denen sie dort zur Gültigkeit gehört. Wenn sein Name erwähnt wird, ist der Segen nach einer bekannten hanafitischen Meinung (aṭ-Ṭaḥāwī) jedes Mal wādschib; nach anderen innerhalb der Schule wādschib einmal pro Sitzung und darüber hinaus empfohlen. (2) Scheidung vor dem Vollzug (33:49): Es gibt keine Wartezeit, und die Frau erhält die Hälfte der vereinbarten Brautgabe. Eine hanafitische Besonderheit: Eine „gültige Zurückgezogenheit“ (chalwa ṣaḥīḥa), also ein ungestörtes Alleinsein der Eheleute ohne Hindernis, wird bezüglich der vollen Brautgabe und der Wartezeit wie der Vollzug behandelt. (3) Adoption (33:4–5): Die Aufnahme und Versorgung eines Kindes (kafāla) ist erlaubt und verdienstvoll; das Kind behält aber den Namen seines leiblichen Vaters und erbt nicht automatisch – es kann durch ein Vermächtnis im Rahmen eines Drittels bedacht werden.",
umsetzung: [
 "Sprich jeden Tag bewusst Segen über den Propheten ﷺ – mindestens zehnmal morgens und zehnmal abends, und besonders am Freitag. Für jedes einmal spricht Allah zehnmal Segen über dich (Muslim 408).",
 "Nimm dir für eine Krise in deinem Leben 33:21 vor: Wie hat sich der Prophet ﷺ am Graben verhalten? Er grub mit, er hungerte mit, er machte Mut – nicht vom Schreibtisch aus.",
 "Prüfe deine Reaktion auf Schwierigkeiten: Sagst du wie die Heuchler „Das war alles Trug“ oder wie die Gläubigen „Das ist, was Allah uns versprochen hat“ (33:12 und 33:22)?",
 "Mach 33:35 zur Grundlage, wenn über Männer und Frauen im Islam gesprochen wird: zehn gleiche Tugenden, gleicher Lohn.",
 "Übe qaulan sadīdā (33:70): Bevor du sprichst, prüfe, ob dein Wort wahr, treffend und nützlich ist – besonders in Streit und in sozialen Medien.",
 "Wenn du ein Kind in Pflege oder Obhut hast oder es planst: Kafāla ist eine große Sunna – die Regeln zu Name und Erbe aus 33:4–5 schützen das Kind und seine Herkunft."
]
}
];
